{
  "name": "GitGenius Pusher",
  "description": "A powerful client-side tool to upload local project folders to GitHub repositories using the GitHub API, featuring AI-powered commit message generation via Gemini."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface FileData {
  path: string;
  content: string | ArrayBuffer;
  isBinary: boolean;
  size: number;
}

export enum UploadStatus {
  IDLE = 'IDLE',
  READING = 'READING',
  UPLOADING = 'UPLOADING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR',
}

export interface GitHubRepo {
  owner: string;
  name: string;
  defaultBranch: string;
}

export interface ProcessingLog {
  message: string;
  type: 'info' | 'success' | 'error';
  timestamp: number;
}

import { FileData } from '../types';

const GITHUB_API_BASE = 'https://api.github.com';

interface GitBlob {
  sha: string;
  path: string;
  mode: string;
  type: string;
}

// Helper to encode array buffer to base64
function arrayBufferToBase64(buffer: ArrayBuffer): string {
  let binary = '';
  const bytes = new Uint8Array(buffer);
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return window.btoa(binary);
}

export const validateToken = async (token: string): Promise<string | null> => {
  try {
    const response = await fetch(`${GITHUB_API_BASE}/user`, {
      headers: {
        Authorization: `token ${token}`,
        Accept: 'application/vnd.github.v3+json',
      },
    });
    if (!response.ok) return null;
    const data = await response.json();
    return data.login; // Return username
  } catch (e) {
    return null;
  }
};

export const checkRepoExists = async (token: string, owner: string, repo: string): Promise<boolean> => {
  const response = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}`, {
    headers: { Authorization: `token ${token}` },
  });
  return response.status === 200;
};

export const createRepo = async (token: string, name: string, isPrivate: boolean): Promise<boolean> => {
  const response = await fetch(`${GITHUB_API_BASE}/user/repos`, {
    method: 'POST',
    headers: {
      Authorization: `token ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      name,
      private: isPrivate,
      auto_init: true, // Initialize so we have a main branch
    }),
  });
  return response.ok;
};

// Core logic: Push files using Git Database API
// This avoids cloning the repo. We create blobs, a tree, and a commit manually.
export const pushFilesToGitHub = async (
  token: string,
  owner: string,
  repo: string,
  branch: string,
  files: FileData[],
  commitMessage: string,
  onProgress: (msg: string) => void
): Promise<void> => {
  const headers = {
    Authorization: `token ${token}`,
    Accept: 'application/vnd.github.v3+json',
    'Content-Type': 'application/json',
  };

  // 1. Get reference to current head
  onProgress('Fetching repository status...');
  let latestCommitSha: string | null = null;
  let baseTreeSha: string | null = null;

  try {
    const refRes = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/git/refs/heads/${branch}`, { headers });
    if (refRes.ok) {
      const refData = await refRes.json();
      latestCommitSha = refData.object.sha;

      const commitRes = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/git/commits/${latestCommitSha}`, { headers });
      const commitData = await commitRes.json();
      baseTreeSha = commitData.tree.sha;
    } else {
      // If branch doesn't exist, we might be dealing with a truly empty repo or need to create the branch
      // However, creating a repo with `auto_init` usually creates main/master.
      // If completely empty, we proceed without parents (root commit).
      onProgress('Branch not found. Starting fresh commit tree.');
    }
  } catch (e) {
    console.warn('Could not fetch refs, assuming empty repo.');
  }

  // 2. Create Blobs for each file
  const treeItems: { path: string; mode: string; type: string; sha: string | null }[] = [];

  // Parallelize uploads in chunks to avoid hitting browser limits or API rate limits aggressively
  const CHUNK_SIZE = 5;
  for (let i = 0; i < files.length; i += CHUNK_SIZE) {
    const chunk = files.slice(i, i + CHUNK_SIZE);
    await Promise.all(chunk.map(async (file) => {
      onProgress(`Uploading ${file.path}...`);

      let content: string;
      let encoding: 'utf-8' | 'base64';

      if (file.isBinary && file.content instanceof ArrayBuffer) {
        content = arrayBufferToBase64(file.content);
        encoding = 'base64';
      } else {
        content = file.content as string;
        encoding = 'utf-8';
      }

      try {
        const blobRes = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/git/blobs`, {
          method: 'POST',
          headers,
          body: JSON.stringify({ content, encoding }),
        });

        if (!blobRes.ok) throw new Error(`Failed to upload ${file.path}`);

        const blobData = await blobRes.json();
        treeItems.push({
          path: file.path,
          mode: '100644', // 100644 for file (blob), 100755 for executable (blob), 040000 for subdirectory (tree)
          type: 'blob',
          sha: blobData.sha,
        });
      } catch (e) {
        onProgress(`Error uploading ${file.path}: ${e}`);
        throw e;
      }
    }));
  }

  // 3. Create a Tree
  onProgress('Building file tree...');
  const treePayload: any = {
    tree: treeItems,
  };

  if (baseTreeSha) {
    treePayload.base_tree = baseTreeSha;
  }

  const treeRes = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/git/trees`, {
    method: 'POST',
    headers,
    body: JSON.stringify(treePayload),
  });

  if (!treeRes.ok) {
      const err = await treeRes.text();
      throw new Error(`Failed to create tree: ${err}`);
  }
  const treeData = await treeRes.json();
  const newTreeSha = treeData.sha;

  // 4. Create Commit
  onProgress('Finalizing commit...');
  const commitPayload: any = {
    message: commitMessage,
    tree: newTreeSha,
  };
  if (latestCommitSha) {
    commitPayload.parents = [latestCommitSha];
  }

  const newCommitRes = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/git/commits`, {
    method: 'POST',
    headers,
    body: JSON.stringify(commitPayload),
  });

  if (!newCommitRes.ok) throw new Error('Failed to create commit');
  const newCommitData = await newCommitRes.json();
  const newCommitSha = newCommitData.sha;

  // 5. Update Reference (The actual "Push")
  onProgress('Pushing to branch...');
  // If branch didn't exist, we create it. If it did, we update it.
  const refUrl = latestCommitSha 
    ? `${GITHUB_API_BASE}/repos/${owner}/${repo}/git/refs/heads/${branch}`
    : `${GITHUB_API_BASE}/repos/${owner}/${repo}/git/refs`;

  const method = latestCommitSha ? 'PATCH' : 'POST';
  const body = latestCommitSha 
    ? { sha: newCommitSha }
    : { ref: `refs/heads/${branch}`, sha: newCommitSha };

  const finalRes = await fetch(refUrl, {
    method,
    headers,
    body: JSON.stringify(body),
  });

  if (!finalRes.ok) throw new Error('Failed to update branch reference');
  onProgress('Push complete!');
};

import { GoogleGenAI } from "@google/genai";
import { FileData } from "../types";

// Safety check for API Key
const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

export const generateCommitMessage = async (files: FileData[], repoName: string): Promise<string> => {
  if (!API_KEY) {
    console.error("Gemini API Key is missing");
    return "Initial commit (Gemini key missing)";
  }

  // To save tokens and avoid limits, we send file names and summaries of small text files (e.g., README, package.json)
  const fileSummaries = files.map(f => {
    let contentPreview = '';
    if (!f.isBinary && typeof f.content === 'string') {
        // Only include the first 200 chars of config-like files
        if (f.path.includes('json') || f.path.includes('md') || f.path.includes('config')) {
            contentPreview = `\nContent Preview: ${f.content.substring(0, 200)}...`;
        }
    }
    return `- ${f.path} ${contentPreview}`;
  }).slice(0, 50).join('\n'); // Limit to first 50 files to avoid massive prompts

  const prompt = `
    I am pushing a project named "${repoName}" to GitHub.
    Here is a list of changed/new files:
    ${fileSummaries}

    ${files.length > 50 ? `...and ${files.length - 50} more files.` : ''}

    Generate a concise, professional Git commit message following Conventional Commits format (e.g., "feat: ...", "chore: ...").
    Do not include any markdown formatting, backticks, or explanations. Just the message string.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text.trim();
  } catch (error) {
    console.error("Gemini Error:", error);
    return `feat: initialize project ${repoName}`;
  }
};

import React from 'react';

interface StepIndicatorProps {
  currentStep: number;
}

const steps = ['Auth', 'Repo', 'Files', 'Review'];

export const StepIndicator: React.FC<StepIndicatorProps> = ({ currentStep }) => {
  return (
    <div className="flex items-center justify-center w-full mb-8">
      {steps.map((label, idx) => {
        const stepNum = idx + 1;
        const isActive = stepNum === currentStep;
        const isCompleted = stepNum < currentStep;

        return (
          <div key={label} className="flex items-center">
            <div className={`flex items-center justify-center w-10 h-10 rounded-full border-2 font-bold transition-all duration-300
              ${isActive ? 'border-blue-500 text-blue-500 bg-blue-500/10 shadow-[0_0_15px_rgba(59,130,246,0.5)]' : 
                isCompleted ? 'border-green-500 text-green-500 bg-green-500/10' : 'border-slate-700 text-slate-500 bg-slate-800'
              }
            `}>
              {isCompleted ? '✓' : stepNum}
            </div>
            <span className={`ml-2 mr-6 text-sm font-medium ${isActive ? 'text-blue-400' : isCompleted ? 'text-green-400' : 'text-slate-600'}`}>
              {label}
            </span>
            {idx < steps.length - 1 && (
              <div className={`h-1 w-12 mr-4 rounded ${isCompleted ? 'bg-green-500/50' : 'bg-slate-800'}`} />
            )}
          </div>
        );
      })}
    </div>
  );
};

import React, { useRef, useState } from 'react';
import { FileData } from '../types';

interface FileUploaderProps {
  onFilesSelected: (files: FileData[]) => void;
}

export const FileUploader: React.FC<FileUploaderProps> = ({ onFilesSelected }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setIsProcessing(true);
      const files: FileData[] = [];
      const fileList = Array.from(e.target.files);

      // Process files
      for (const file of fileList) {
        // Exclude node_modules and .git folders for sanity
        if (file.webkitRelativePath.includes('node_modules') || file.webkitRelativePath.includes('.git/')) {
          continue;
        }

        const isBinary = isBinaryFile(file.name);
        const content = await readFileContent(file, isBinary);

        files.push({
          path: file.webkitRelativePath, // Preserves folder structure
          content,
          isBinary,
          size: file.size,
        });
      }

      onFilesSelected(files);
      setIsProcessing(false);
    }
  };

  const isBinaryFile = (fileName: string): boolean => {
    const extensions = ['png', 'jpg', 'jpeg', 'gif', 'ico', 'pdf', 'zip', 'exe', 'bin', 'mp4', 'mp3', 'woff', 'woff2', 'ttf'];
    const ext = fileName.split('.').pop()?.toLowerCase();
    return ext ? extensions.includes(ext) : false;
  };

  const readFileContent = (file: File, isBinary: boolean): Promise<string | ArrayBuffer> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        if (e.target?.result) resolve(e.target.result);
        else reject(new Error("Empty file"));
      };
      reader.onerror = (e) => reject(e);

      if (isBinary) {
        reader.readAsArrayBuffer(file);
      } else {
        reader.readAsText(file);
      }
    });
  };

  return (
    <div className="w-full flex flex-col items-center justify-center p-8 border-2 border-dashed border-slate-700 rounded-xl bg-slate-800/50 hover:bg-slate-800 transition-colors">
      <div className="mb-4 text-6xl">📂</div>
      <h3 className="text-xl font-semibold mb-2 text-slate-200">Select Project Folder</h3>
      <p className="text-slate-400 text-center mb-6 max-w-md">
        Click to select a directory to push. Binary files and text files will be processed automatically. 
        <br/><span className="text-xs text-yellow-500/80">(node_modules and .git are automatically ignored)</span>
      </p>

      {isProcessing ? (
        <div className="flex items-center text-blue-400">
          <svg className="animate-spin h-5 w-5 mr-3" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
          Processing files...
        </div>
      ) : (
        <button
          onClick={() => fileInputRef.current?.click()}
          className="bg-blue-600 hover:bg-blue-500 text-white font-semibold py-3 px-8 rounded-lg shadow-lg shadow-blue-500/30 transition-all transform hover:scale-105"
        >
          Browse Folder
        </button>
      )}

      {/* 
        IMPORTANT: webkitdirectory attribute is non-standard but needed for folder selection.
        React TS doesn't natively support it on input types without module augmentation or casting.
      */}
      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChange}
        className="hidden"
        {...({ webkitdirectory: "", directory: "" } as any)} 
      />
    </div>
  );
};

import React, { useState } from 'react';
import { StepIndicator } from './components/StepIndicator';
import { FileUploader } from './components/FileUploader';
import { FileData, UploadStatus, ProcessingLog } from './types';
import * as githubService from './services/githubService';
import * as geminiService from './services/geminiService';

export default function App() {
  const [step, setStep] = useState(1);

  // State: Auth
  const [token, setToken] = useState('');
  const [username, setUsername] = useState<string | null>(null);

  // State: Repo
  const [repoName, setRepoName] = useState('');
  const [isPrivate, setIsPrivate] = useState(true);
  const [branch, setBranch] = useState('main');

  // State: Files
  const [files, setFiles] = useState<FileData[]>([]);

  // State: Commit & Push
  const [commitMessage, setCommitMessage] = useState('');
  const [status, setStatus] = useState<UploadStatus>(UploadStatus.IDLE);
  const [logs, setLogs] = useState<ProcessingLog[]>([]);
  const [isGeneratingMsg, setIsGeneratingMsg] = useState(false);

  const addLog = (msg: string, type: 'info' | 'success' | 'error' = 'info') => {
    setLogs(prev => [...prev, { message: msg, type, timestamp: Date.now() }]);
  };

  // --- Step 1: Auth ---
  const handleTokenSubmit = async () => {
    if (!token) return;
    setStatus(UploadStatus.READING);
    const user = await githubService.validateToken(token);
    if (user) {
      setUsername(user);
      setStep(2);
      setStatus(UploadStatus.IDLE);
    } else {
      alert("Invalid GitHub Token");
      setStatus(UploadStatus.IDLE);
    }
  };

  // --- Step 2: Repo ---
  const handleRepoSubmit = async () => {
    if (!repoName || !username) return;
    setStatus(UploadStatus.READING);

    // Check if repo exists
    const exists = await githubService.checkRepoExists(token, username, repoName);

    if (exists) {
      // It exists, we will push to it
      addLog(`Repository ${repoName} found.`, 'success');
      setStep(3);
    } else {
      // Create it
      try {
        addLog(`Creating repository ${repoName}...`, 'info');
        const created = await githubService.createRepo(token, repoName, isPrivate);
        if (created) {
          addLog(`Repository ${repoName} created successfully.`, 'success');
          setStep(3);
        } else {
          addLog("Failed to create repository", 'error');
        }
      } catch (e) {
        addLog("Error creating repository", 'error');
      }
    }
    setStatus(UploadStatus.IDLE);
  };

  // --- Step 3: Files ---
  const handleFilesSelected = (selectedFiles: FileData[]) => {
    if (selectedFiles.length === 0) return;
    setFiles(selectedFiles);
    setStep(4);
    // Auto-generate commit message suggestion
    handleGenerateCommitMessage(selectedFiles);
  };

  const handleGenerateCommitMessage = async (currentFiles: FileData[]) => {
    setIsGeneratingMsg(true);
    const msg = await geminiService.generateCommitMessage(currentFiles, repoName);
    setCommitMessage(msg);
    setIsGeneratingMsg(false);
  };

  // --- Step 4: Push ---
  const handlePush = async () => {
    if (!username || !repoName || files.length === 0) return;
    setStatus(UploadStatus.UPLOADING);
    setLogs([]); // Clear previous logs

    try {
      addLog('Starting upload process...', 'info');
      await githubService.pushFilesToGitHub(
        token,
        username,
        repoName,
        branch,
        files,
        commitMessage || "Update project files",
        (msg) => addLog(msg, 'info')
      );
      setStatus(UploadStatus.SUCCESS);
      addLog('Project pushed successfully!', 'success');
    } catch (error: any) {
      console.error(error);
      setStatus(UploadStatus.ERROR);
      addLog(`Error: ${error.message}`, 'error');
    }
  };

  const reset = () => {
    setFiles([]);
    setStep(2);
    setStatus(UploadStatus.IDLE);
    setLogs([]);
    setCommitMessage('');
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-50 flex flex-col items-center py-12 px-4">
      <div className="w-full max-w-4xl">
        <header className="mb-10 text-center">
          <h1 className="text-4xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-500 mb-2">
            GitGenius Pusher
          </h1>
          <p className="text-slate-400">Push local folders to GitHub directly from your browser.</p>
        </header>

        <StepIndicator currentStep={step} />

        <div className="bg-slate-800 rounded-2xl shadow-2xl border border-slate-700 p-8 min-h-[400px]">

          {/* STEP 1: AUTH */}
          {step === 1 && (
            <div className="flex flex-col gap-6 max-w-md mx-auto mt-8">
              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-300">GitHub Personal Access Token (Classic)</label>
                <input
                  type="password"
                  value={token}
                  onChange={(e) => setToken(e.target.value)}
                  placeholder="ghp_xxxxxxxxxxxx"
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                />
                <p className="text-xs text-slate-500">
                  Required scopes: <code>repo</code>, <code>user</code>. The token is only used locally and never stored on a server.
                </p>
              </div>
              <button
                onClick={handleTokenSubmit}
                disabled={status === UploadStatus.READING}
                className="w-full bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-3 px-6 rounded-lg transition-colors"
              >
                {status === UploadStatus.READING ? 'Verifying...' : 'Connect to GitHub'}
              </button>
            </div>
          )}

          {/* STEP 2: REPO DETAILS */}
          {step === 2 && (
            <div className="flex flex-col gap-6 max-w-md mx-auto mt-4">
              <div className="text-center mb-4">
                <p className="text-slate-400">Logged in as <span className="text-white font-bold">{username}</span></p>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-300">Repository Name</label>
                <input
                  type="text"
                  value={repoName}
                  onChange={(e) => setRepoName(e.target.value)}
                  placeholder="my-awesome-project"
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-300">Branch</label>
                <input
                  type="text"
                  value={branch}
                  onChange={(e) => setBranch(e.target.value)}
                  placeholder="main"
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                />
              </div>

              <div className="flex items-center gap-4 bg-slate-900 p-4 rounded-lg border border-slate-700">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    checked={isPrivate}
                    onChange={() => setIsPrivate(true)}
                    className="w-4 h-4 text-blue-500"
                  />
                  <span>Private</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    checked={!isPrivate}
                    onChange={() => setIsPrivate(false)}
                    className="w-4 h-4 text-blue-500"
                  />
                  <span>Public</span>
                </label>
              </div>

              <button
                onClick={handleRepoSubmit}
                disabled={!repoName || status === UploadStatus.READING}
                className="w-full bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white font-bold py-3 px-6 rounded-lg transition-colors"
              >
                {status === UploadStatus.READING ? 'Checking Repo...' : 'Next: Select Files'}
              </button>
            </div>
          )}

          {/* STEP 3: UPLOAD */}
          {step === 3 && (
            <div className="mt-8">
               <FileUploader onFilesSelected={handleFilesSelected} />
               <div className="mt-4 text-center">
                 <button onClick={() => setStep(2)} className="text-slate-400 hover:text-white underline text-sm">Back to Repo Settings</button>
               </div>
            </div>
          )}

          {/* STEP 4: REVIEW & PUSH */}
          {step === 4 && (
            <div className="flex flex-col lg:flex-row gap-8 h-full">
              {/* Left Col: File Summary */}
              <div className="flex-1 space-y-4">
                <h3 className="text-xl font-bold text-white flex items-center">
                  <span className="mr-2">📄</span> {files.length} Files Ready
                </h3>
                <div className="bg-slate-900 rounded-lg p-4 h-64 overflow-y-auto border border-slate-700">
                  <ul className="space-y-2 text-sm text-slate-300">
                    {files.slice(0, 100).map((f, i) => (
                      <li key={i} className="flex justify-between truncate">
                        <span className="truncate">{f.path}</span>
                        <span className="text-xs text-slate-600 ml-2">{(f.size / 1024).toFixed(1)} KB</span>
                      </li>
                    ))}
                    {files.length > 100 && (
                      <li className="text-center text-slate-500 italic pt-2">...and {files.length - 100} more</li>
                    )}
                  </ul>
                </div>
              </div>

              {/* Right Col: Commit Actions */}
              <div className="flex-1 space-y-6">
                <div className="space-y-2">
                  <div className="flex justify-between items-center">
                    <label className="text-sm font-bold text-slate-300">Commit Message</label>
                    <button 
                      onClick={() => handleGenerateCommitMessage(files)}
                      disabled={isGeneratingMsg}
                      className="text-xs bg-purple-600/20 text-purple-300 hover:bg-purple-600/40 px-2 py-1 rounded transition-colors flex items-center gap-1 border border-purple-500/30"
                    >
                      {isGeneratingMsg ? (
                        <span className="animate-pulse">Thinking...</span>
                      ) : (
                        <>✨ Rewrite with Gemini</>
                      )}
                    </button>
                  </div>
                  <textarea
                    value={commitMessage}
                    onChange={(e) => setCommitMessage(e.target.value)}
                    className="w-full h-32 bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none resize-none font-mono text-sm"
                    placeholder="feat: initial commit"
                  />
                </div>

                {status === UploadStatus.IDLE || status === UploadStatus.ERROR ? (
                   <button
                   onClick={handlePush}
                   className="w-full bg-green-600 hover:bg-green-500 text-white font-bold py-4 px-6 rounded-lg shadow-lg shadow-green-500/20 transition-all transform hover:scale-[1.02]"
                 >
                   🚀 Push to GitHub
                 </button>
                ) : (
                  <div className="bg-slate-900 rounded-lg p-4 border border-slate-700 h-40 overflow-y-auto">
                    {status === UploadStatus.SUCCESS ? (
                      <div className="flex flex-col items-center justify-center h-full text-green-400">
                         <span className="text-4xl mb-2">🎉</span>
                         <span className="font-bold">Upload Complete!</span>
                         <a 
                            href={`https://github.com/${username}/${repoName}/tree/${branch}`} 
                            target="_blank" 
                            rel="noreferrer"
                            className="mt-2 text-blue-400 hover:underline"
                          >
                            View Repository
                         </a>
                         <button onClick={reset} className="mt-4 text-xs text-slate-500 hover:text-white">Push another project</button>
                      </div>
                    ) : (
                      <div className="font-mono text-xs space-y-1">
                        {logs.map((log, i) => (
                          <div key={i} className={`${
                            log.type === 'error' ? 'text-red-400' : 
                            log.type === 'success' ? 'text-green-400' : 'text-slate-400'
                          }`}>
                            <span className="opacity-50">[{new Date(log.timestamp).toLocaleTimeString()}]</span> {log.message}
                          </div>
                        ))}
                        <div ref={(el) => el?.scrollIntoView({ behavior: 'smooth' })} />
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          )}

        </div>
      </div>
    </div>
  );
}

import React, { useRef, useState } from 'react';
import { FileData } from '../types';

interface FileUploaderProps {
  onFilesSelected: (files: FileData[]) => void;
}

export const FileUploader: React.FC<FileUploaderProps> = ({ onFilesSelected }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setIsProcessing(true);
      const files: FileData[] = [];
      // Explicitly cast to File[] to fix 'unknown' type inference error
      const fileList = Array.from(e.target.files) as File[];

      // Process files
      for (const file of fileList) {
        // webkitRelativePath is available when uploading directories
        const relativePath = file.webkitRelativePath || file.name;

        // Exclude node_modules and .git folders for sanity
        if (relativePath.includes('node_modules') || relativePath.includes('.git/')) {
          continue;
        }

        const isBinary = isBinaryFile(file.name);
        try {
          const content = await readFileContent(file, isBinary);

          files.push({
            path: relativePath, // Preserves folder structure
            content,
            isBinary,
            size: file.size,
          });
        } catch (err) {
          console.warn(`Skipping file ${file.name}:`, err);
        }
      }

      onFilesSelected(files);
      setIsProcessing(false);
    }
  };

  const isBinaryFile = (fileName: string): boolean => {
    const extensions = ['png', 'jpg', 'jpeg', 'gif', 'ico', 'pdf', 'zip', 'exe', 'bin', 'mp4', 'mp3', 'woff', 'woff2', 'ttf'];
    const ext = fileName.split('.').pop()?.toLowerCase();
    return ext ? extensions.includes(ext) : false;
  };

  const readFileContent = (file: File, isBinary: boolean): Promise<string | ArrayBuffer> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        if (e.target?.result) resolve(e.target.result);
        else reject(new Error("Empty file"));
      };
      reader.onerror = (e) => reject(e);

      if (isBinary) {
        reader.readAsArrayBuffer(file);
      } else {
        reader.readAsText(file);
      }
    });
  };

  return (
    <div className="w-full flex flex-col items-center justify-center p-8 border-2 border-dashed border-slate-700 rounded-xl bg-slate-800/50 hover:bg-slate-800 transition-colors">
      <div className="mb-4 text-6xl">📂</div>
      <h3 className="text-xl font-semibold mb-2 text-slate-200">Select Project Folder</h3>
      <p className="text-slate-400 text-center mb-6 max-w-md">
        Click to select a directory to push. Binary files and text files will be processed automatically. 
        <br/><span className="text-xs text-yellow-500/80">(node_modules and .git are automatically ignored)</span>
      </p>

      {isProcessing ? (
        <div className="flex items-center text-blue-400">
          <svg className="animate-spin h-5 w-5 mr-3" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
          Processing files...
        </div>
      ) : (
        <button
          onClick={() => fileInputRef.current?.click()}
          className="bg-blue-600 hover:bg-blue-500 text-white font-semibold py-3 px-8 rounded-lg shadow-lg shadow-blue-500/30 transition-all transform hover:scale-105"
        >
          Browse Folder
        </button>
      )}

      {/* 
        IMPORTANT: webkitdirectory attribute is non-standard but needed for folder selection.
        React TS doesn't natively support it on input types without module augmentation or casting.
      */}
      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChange}
        className="hidden"
        {...({ webkitdirectory: "", directory: "" } as any)} 
      />
    </div>
  );
};

export interface FileData {
  path: string;
  content: string | ArrayBuffer;
  isBinary: boolean;
  size: number;
}

export enum UploadStatus {
  IDLE = 'IDLE',
  READING = 'READING',
  UPLOADING = 'UPLOADING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR',
}

export interface GitHubRepo {
  id: number;
  name: string;
  full_name: string;
  private: boolean;
  default_branch: string;
  owner: {
    login: string;
  };
  html_url: string;
  description: string | null;
}

export interface ProcessingLog {
  message: string;
  type: 'info' | 'success' | 'error';
  timestamp: number;
}

import { FileData, GitHubRepo } from '../types';

const GITHUB_API_BASE = 'https://api.github.com';

interface GitBlob {
  sha: string;
  path: string;
  mode: string;
  type: string;
}

// Helper to encode array buffer to base64
function arrayBufferToBase64(buffer: ArrayBuffer): string {
  let binary = '';
  const bytes = new Uint8Array(buffer);
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return window.btoa(binary);
}

export const validateToken = async (token: string): Promise<string | null> => {
  try {
    const response = await fetch(`${GITHUB_API_BASE}/user`, {
      headers: {
        Authorization: `token ${token}`,
        Accept: 'application/vnd.github.v3+json',
      },
    });
    if (!response.ok) return null;
    const data = await response.json();
    return data.login; // Return username
  } catch (e) {
    return null;
  }
};

export const getUserRepos = async (token: string): Promise<GitHubRepo[]> => {
  try {
    // Fetch up to 100 recently updated repos
    const response = await fetch(`${GITHUB_API_BASE}/user/repos?sort=updated&per_page=100`, {
      headers: {
        Authorization: `token ${token}`,
        Accept: 'application/vnd.github.v3+json',
      },
    });
    if (!response.ok) return [];
    return await response.json();
  } catch (e) {
    console.error("Error fetching repos:", e);
    return [];
  }
};

export const checkRepoExists = async (token: string, owner: string, repo: string): Promise<boolean> => {
  const response = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}`, {
    headers: { Authorization: `token ${token}` },
  });
  return response.status === 200;
};

export const createRepo = async (token: string, name: string, isPrivate: boolean): Promise<boolean> => {
  const response = await fetch(`${GITHUB_API_BASE}/user/repos`, {
    method: 'POST',
    headers: {
      Authorization: `token ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      name,
      private: isPrivate,
      auto_init: true, // Initialize so we have a main branch
    }),
  });
  return response.ok;
};

// Core logic: Push files using Git Database API
// This avoids cloning the repo. We create blobs, a tree, and a commit manually.
export const pushFilesToGitHub = async (
  token: string,
  owner: string,
  repo: string,
  branch: string,
  files: FileData[],
  commitMessage: string,
  onProgress: (msg: string) => void
): Promise<void> => {
  const headers = {
    Authorization: `token ${token}`,
    Accept: 'application/vnd.github.v3+json',
    'Content-Type': 'application/json',
  };

  // 1. Get reference to current head
  onProgress('Fetching repository status...');
  let latestCommitSha: string | null = null;
  let baseTreeSha: string | null = null;

  try {
    const refRes = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/git/refs/heads/${branch}`, { headers });
    if (refRes.ok) {
      const refData = await refRes.json();
      latestCommitSha = refData.object.sha;

      const commitRes = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/git/commits/${latestCommitSha}`, { headers });
      const commitData = await commitRes.json();
      baseTreeSha = commitData.tree.sha;
    } else {
      // If branch doesn't exist, we might be dealing with a truly empty repo or need to create the branch
      // However, creating a repo with `auto_init` usually creates main/master.
      // If completely empty, we proceed without parents (root commit).
      onProgress('Branch not found. Starting fresh commit tree.');
    }
  } catch (e) {
    console.warn('Could not fetch refs, assuming empty repo.');
  }

  // 2. Create Blobs for each file
  const treeItems: { path: string; mode: string; type: string; sha: string | null }[] = [];

  // Parallelize uploads in chunks to avoid hitting browser limits or API rate limits aggressively
  const CHUNK_SIZE = 5;
  for (let i = 0; i < files.length; i += CHUNK_SIZE) {
    const chunk = files.slice(i, i + CHUNK_SIZE);
    await Promise.all(chunk.map(async (file) => {
      onProgress(`Uploading ${file.path}...`);

      let content: string;
      let encoding: 'utf-8' | 'base64';

      if (file.isBinary && file.content instanceof ArrayBuffer) {
        content = arrayBufferToBase64(file.content);
        encoding = 'base64';
      } else {
        content = file.content as string;
        encoding = 'utf-8';
      }

      try {
        const blobRes = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/git/blobs`, {
          method: 'POST',
          headers,
          body: JSON.stringify({ content, encoding }),
        });

        if (!blobRes.ok) throw new Error(`Failed to upload ${file.path}`);

        const blobData = await blobRes.json();
        treeItems.push({
          path: file.path,
          mode: '100644', // 100644 for file (blob), 100755 for executable (blob), 040000 for subdirectory (tree)
          type: 'blob',
          sha: blobData.sha,
        });
      } catch (e) {
        onProgress(`Error uploading ${file.path}: ${e}`);
        throw e;
      }
    }));
  }

  // 3. Create a Tree
  onProgress('Building file tree...');
  const treePayload: any = {
    tree: treeItems,
  };

  if (baseTreeSha) {
    treePayload.base_tree = baseTreeSha;
  }

  const treeRes = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/git/trees`, {
    method: 'POST',
    headers,
    body: JSON.stringify(treePayload),
  });

  if (!treeRes.ok) {
      const err = await treeRes.text();
      throw new Error(`Failed to create tree: ${err}`);
  }
  const treeData = await treeRes.json();
  const newTreeSha = treeData.sha;

  // 4. Create Commit
  onProgress('Finalizing commit...');
  const commitPayload: any = {
    message: commitMessage,
    tree: newTreeSha,
  };
  if (latestCommitSha) {
    commitPayload.parents = [latestCommitSha];
  }

  const newCommitRes = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/git/commits`, {
    method: 'POST',
    headers,
    body: JSON.stringify(commitPayload),
  });

  if (!newCommitRes.ok) throw new Error('Failed to create commit');
  const newCommitData = await newCommitRes.json();
  const newCommitSha = newCommitData.sha;

  // 5. Update Reference (The actual "Push")
  onProgress('Pushing to branch...');
  // If branch didn't exist, we create it. If it did, we update it.
  const refUrl = latestCommitSha 
    ? `${GITHUB_API_BASE}/repos/${owner}/${repo}/git/refs/heads/${branch}`
    : `${GITHUB_API_BASE}/repos/${owner}/${repo}/git/refs`;

  const method = latestCommitSha ? 'PATCH' : 'POST';
  const body = latestCommitSha 
    ? { sha: newCommitSha }
    : { ref: `refs/heads/${branch}`, sha: newCommitSha };

  const finalRes = await fetch(refUrl, {
    method,
    headers,
    body: JSON.stringify(body),
  });

  if (!finalRes.ok) throw new Error('Failed to update branch reference');
  onProgress('Push complete!');
};

import React, { useState, useEffect } from 'react';
import { StepIndicator } from './components/StepIndicator';
import { FileUploader } from './components/FileUploader';
import { FileData, UploadStatus, ProcessingLog, GitHubRepo } from './types';
import * as githubService from './services/githubService';
import * as geminiService from './services/geminiService';

export default function App() {
  const [step, setStep] = useState(1);

  // State: Auth
  const [token, setToken] = useState('');
  const [username, setUsername] = useState<string | null>(null);

  // State: Repo
  const [repoMode, setRepoMode] = useState<'create' | 'existing'>('create');
  const [userRepos, setUserRepos] = useState<GitHubRepo[]>([]);
  const [isLoadingRepos, setIsLoadingRepos] = useState(false);
  const [searchRepo, setSearchRepo] = useState('');

  const [repoName, setRepoName] = useState('');
  const [repoOwner, setRepoOwner] = useState('');
  const [isPrivate, setIsPrivate] = useState(true);
  const [branch, setBranch] = useState('main');

  // State: Files
  const [files, setFiles] = useState<FileData[]>([]);

  // State: Commit & Push
  const [commitMessage, setCommitMessage] = useState('');
  const [status, setStatus] = useState<UploadStatus>(UploadStatus.IDLE);
  const [logs, setLogs] = useState<ProcessingLog[]>([]);
  const [isGeneratingMsg, setIsGeneratingMsg] = useState(false);

  const addLog = (msg: string, type: 'info' | 'success' | 'error' = 'info') => {
    setLogs(prev => [...prev, { message: msg, type, timestamp: Date.now() }]);
  };

  // Fetch repos when entering Step 2
  useEffect(() => {
    if (step === 2 && token && userRepos.length === 0) {
      loadRepos();
    }
  }, [step, token]);

  const loadRepos = async () => {
    setIsLoadingRepos(true);
    const repos = await githubService.getUserRepos(token);
    setUserRepos(repos);
    setIsLoadingRepos(false);
  };

  // --- Step 1: Auth ---
  const handleTokenSubmit = async () => {
    if (!token) return;
    setStatus(UploadStatus.READING);
    const user = await githubService.validateToken(token);
    if (user) {
      setUsername(user);
      setRepoOwner(user); // Default owner is the authenticated user
      setStep(2);
      setStatus(UploadStatus.IDLE);
    } else {
      alert("Invalid GitHub Token");
      setStatus(UploadStatus.IDLE);
    }
  };

  // --- Step 2: Repo ---
  const handleRepoSubmit = async () => {
    if (!repoName || !repoOwner) return;
    setStatus(UploadStatus.READING);

    // Check if repo exists
    const exists = await githubService.checkRepoExists(token, repoOwner, repoName);

    if (exists) {
      // It exists, we will push to it
      addLog(`Repository ${repoOwner}/${repoName} found.`, 'success');
      setStep(3);
    } else {
      // Create it (only if in create mode or implicit)
      if (repoMode === 'existing') {
        addLog(`Repository ${repoOwner}/${repoName} not found.`, 'error');
        setStatus(UploadStatus.IDLE);
        return;
      }

      try {
        addLog(`Creating repository ${repoName}...`, 'info');
        const created = await githubService.createRepo(token, repoName, isPrivate);
        if (created) {
          addLog(`Repository ${repoName} created successfully.`, 'success');
          setStep(3);
        } else {
          addLog("Failed to create repository", 'error');
        }
      } catch (e) {
        addLog("Error creating repository", 'error');
      }
    }
    setStatus(UploadStatus.IDLE);
  };

  const handleExistingRepoSelect = (repo: GitHubRepo) => {
    setRepoName(repo.name);
    setRepoOwner(repo.owner.login);
    setBranch(repo.default_branch);
    setIsPrivate(repo.private);
  };

  // --- Step 3: Files ---
  const handleFilesSelected = (selectedFiles: FileData[]) => {
    if (selectedFiles.length === 0) return;
    setFiles(selectedFiles);
    setStep(4);
    // Auto-generate commit message suggestion
    handleGenerateCommitMessage(selectedFiles);
  };

  const handleGenerateCommitMessage = async (currentFiles: FileData[]) => {
    setIsGeneratingMsg(true);
    const msg = await geminiService.generateCommitMessage(currentFiles, repoName);
    setCommitMessage(msg);
    setIsGeneratingMsg(false);
  };

  // --- Step 4: Push ---
  const handlePush = async () => {
    if (!repoOwner || !repoName || files.length === 0) return;
    setStatus(UploadStatus.UPLOADING);
    setLogs([]); // Clear previous logs

    try {
      addLog('Starting upload process...', 'info');
      await githubService.pushFilesToGitHub(
        token,
        repoOwner,
        repoName,
        branch,
        files,
        commitMessage || "Update project files",
        (msg) => addLog(msg, 'info')
      );
      setStatus(UploadStatus.SUCCESS);
      addLog('Project pushed successfully!', 'success');
    } catch (error: any) {
      console.error(error);
      setStatus(UploadStatus.ERROR);
      addLog(`Error: ${error.message}`, 'error');
    }
  };

  const reset = () => {
    setFiles([]);
    setStep(2);
    setStatus(UploadStatus.IDLE);
    setLogs([]);
    setCommitMessage('');
  };

  const filteredRepos = userRepos.filter(r => 
    r.full_name.toLowerCase().includes(searchRepo.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-slate-900 text-slate-50 flex flex-col items-center py-12 px-4">
      <div className="w-full max-w-4xl">
        <header className="mb-10 text-center">
          <h1 className="text-4xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-500 mb-2">
            GitGenius Pusher
          </h1>
          <p className="text-slate-400">Push local folders to GitHub directly from your browser.</p>
        </header>

        <StepIndicator currentStep={step} />

        <div className="bg-slate-800 rounded-2xl shadow-2xl border border-slate-700 p-8 min-h-[400px]">

          {/* STEP 1: AUTH */}
          {step === 1 && (
            <div className="flex flex-col gap-6 max-w-md mx-auto mt-8">
              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-300">GitHub Personal Access Token (Classic)</label>
                <input
                  type="password"
                  value={token}
                  onChange={(e) => setToken(e.target.value)}
                  placeholder="ghp_xxxxxxxxxxxx"
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                />
                <p className="text-xs text-slate-500">
                  Required scopes: <code>repo</code>, <code>user</code>. The token is only used locally and never stored on a server.
                </p>
              </div>
              <button
                onClick={handleTokenSubmit}
                disabled={status === UploadStatus.READING}
                className="w-full bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-3 px-6 rounded-lg transition-colors"
              >
                {status === UploadStatus.READING ? 'Verifying...' : 'Connect to GitHub'}
              </button>
            </div>
          )}

          {/* STEP 2: REPO DETAILS */}
          {step === 2 && (
            <div className="flex flex-col gap-6 max-w-md mx-auto mt-4">
              <div className="text-center mb-4">
                <p className="text-slate-400">Logged in as <span className="text-white font-bold">{username}</span></p>
              </div>

              {/* Toggle Mode */}
              <div className="flex p-1 bg-slate-900 rounded-lg mb-4 border border-slate-700">
                <button 
                  onClick={() => { setRepoMode('create'); setRepoName(''); setRepoOwner(username!); }}
                  className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${
                    repoMode === 'create' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'
                  }`}
                >
                  Create New
                </button>
                <button 
                   onClick={() => { setRepoMode('existing'); }}
                   className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${
                    repoMode === 'existing' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'
                   }`}
                >
                  Update Existing
                </button>
              </div>

              {repoMode === 'create' ? (
                <>
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-300">New Repository Name</label>
                    <input
                      type="text"
                      value={repoName}
                      onChange={(e) => setRepoName(e.target.value)}
                      placeholder="my-awesome-project"
                      className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-300">Branch</label>
                    <input
                      type="text"
                      value={branch}
                      onChange={(e) => setBranch(e.target.value)}
                      placeholder="main"
                      className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                    />
                  </div>
                  <div className="flex items-center gap-4 bg-slate-900 p-4 rounded-lg border border-slate-700">
                    <label className="flex items-center gap-2 cursor-pointer">
                      <input type="radio" checked={isPrivate} onChange={() => setIsPrivate(true)} className="w-4 h-4 text-blue-500" />
                      <span>Private</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer">
                      <input type="radio" checked={!isPrivate} onChange={() => setIsPrivate(false)} className="w-4 h-4 text-blue-500" />
                      <span>Public</span>
                    </label>
                  </div>
                </>
              ) : (
                <>
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-300">Select Repository</label>
                    {isLoadingRepos ? (
                      <div className="text-slate-500 text-sm animate-pulse">Loading repositories...</div>
                    ) : (
                      <>
                        <input
                           type="text"
                           value={searchRepo}
                           onChange={(e) => setSearchRepo(e.target.value)}
                           placeholder="Filter repositories..."
                           className="w-full mb-2 bg-slate-900 border border-slate-700 rounded-lg px-4 py-2 text-sm text-white focus:ring-1 focus:ring-blue-500 outline-none"
                        />
                        <div className="max-h-48 overflow-y-auto bg-slate-900 border border-slate-700 rounded-lg">
