                           ) : (
                             filteredRepos.map(repo => (
                               <div 
                                 key={repo.id}
                                 onClick={() => {
                                   handleExistingRepoSelect(repo);
                                   setSearchRepo(repo.full_name);
                                 }}
                                 className={`p-3 cursor-pointer text-sm hover:bg-slate-800 transition-colors flex justify-between items-center
                                   ${repoName === repo.name && repoOwner === repo.owner.login ? 'bg-blue-900/30 text-blue-300' : 'text-slate-300'}
                                 `}
                               >
                                 <span className="truncate pr-2">{repo.full_name}</span>
                                 {repo.private && <span className="text-xs bg-slate-800 border border-slate-600 px-1 rounded">Private</span>}
                               </div>
                             ))
                           )}
                        </div>
                      </>
                    )}
                  </div>
                  {repoName && (
                    <div className="space-y-2 bg-slate-900/50 p-3 rounded border border-slate-700/50">
                        <div className="text-xs text-slate-500">Target: <span className="text-slate-300">{repoOwner}/{repoName}</span></div>
                        <div className="flex items-center gap-2">
                             <label className="text-xs font-bold text-slate-400">Branch:</label>
                             <input 
                                type="text" 
                                value={branch} 
                                onChange={(e) => setBranch(e.target.value)}
                                className="bg-transparent border-b border-slate-600 text-sm text-white focus:border-blue-500 outline-none w-full"
                             />
                        </div>
                    </div>
                  )}
                </>
              )}

              <button
                onClick={handleRepoSubmit}
                disabled={!repoName || status === UploadStatus.READING}
                className="w-full bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white font-bold py-3 px-6 rounded-lg transition-colors mt-2"
              >
                {status === UploadStatus.READING ? 'Checking Repo...' : 'Next: Select Files'}
              </button>
            </div>
          )}

          {/* STEP 3: UPLOAD */}
          {step === 3 && (
            <div className="mt-8">
               <FileUploader onFilesSelected={handleFilesSelected} />
               <div className="mt-4 text-center">
                 <button onClick={() => setStep(2)} className="text-slate-400 hover:text-white underline text-sm">Back to Repo Settings</button>
               </div>
            </div>
          )}

          {/* STEP 4: REVIEW & PUSH */}
          {step === 4 && (
            <div className="flex flex-col lg:flex-row gap-8 h-full">
              {/* Left Col: File Summary */}
              <div className="flex-1 space-y-4">
                <h3 className="text-xl font-bold text-white flex items-center">
                  <span className="mr-2">📄</span> {files.length} Files Ready
                </h3>
                <div className="bg-slate-900 rounded-lg p-4 h-64 overflow-y-auto border border-slate-700">
                  <ul className="space-y-2 text-sm text-slate-300">
                    {files.slice(0, 100).map((f, i) => (
                      <li key={i} className="flex justify-between truncate">
                        <span className="truncate">{f.path}</span>
                        <span className="text-xs text-slate-600 ml-2">{(f.size / 1024).toFixed(1)} KB</span>
                      </li>
                    ))}
                    {files.length > 100 && (
                      <li className="text-center text-slate-500 italic pt-2">...and {files.length - 100} more</li>
                    )}
                  </ul>
                </div>
              </div>

              {/* Right Col: Commit Actions */}
              <div className="flex-1 space-y-6">
                <div className="space-y-2">
                  <div className="flex justify-between items-center">
                    <label className="text-sm font-bold text-slate-300">Commit Message</label>
                    <button 
                      onClick={() => handleGenerateCommitMessage(files)}
                      disabled={isGeneratingMsg}
                      className="text-xs bg-purple-600/20 text-purple-300 hover:bg-purple-600/40 px-2 py-1 rounded transition-colors flex items-center gap-1 border border-purple-500/30"
                    >
                      {isGeneratingMsg ? (
                        <span className="animate-pulse">Thinking...</span>
                      ) : (
                        <>✨ Rewrite with Gemini</>
                      )}
                    </button>
                  </div>
                  <textarea
                    value={commitMessage}
                    onChange={(e) => setCommitMessage(e.target.value)}
                    className="w-full h-32 bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none resize-none font-mono text-sm"
                    placeholder="feat: initial commit"
                  />
                </div>

                {status === UploadStatus.IDLE || status === UploadStatus.ERROR ? (
                   <button
                   onClick={handlePush}
                   className="w-full bg-green-600 hover:bg-green-500 text-white font-bold py-4 px-6 rounded-lg shadow-lg shadow-green-500/20 transition-all transform hover:scale-[1.02]"
                 >
                   🚀 Push to GitHub
                 </button>
                ) : (
                  <div className="bg-slate-900 rounded-lg p-4 border border-slate-700 h-40 overflow-y-auto">
                    {status === UploadStatus.SUCCESS ? (
                      <div className="flex flex-col items-center justify-center h-full text-green-400">
                         <span className="text-4xl mb-2">🎉</span>
                         <span className="font-bold">Upload Complete!</span>
                         <a 
                            href={`https://github.com/${repoOwner}/${repoName}/tree/${branch}`} 
                            target="_blank" 
                            rel="noreferrer"
                            className="mt-2 text-blue-400 hover:underline"
                          >
                            View Repository
                         </a>
                         <button onClick={reset} className="mt-4 text-xs text-slate-500 hover:text-white">Push another project</button>
                      </div>
                    ) : (
                      <div className="font-mono text-xs space-y-1">
                        {logs.map((log, i) => (
                          <div key={i} className={`${
                            log.type === 'error' ? 'text-red-400' : 
                            log.type === 'success' ? 'text-green-400' : 'text-slate-400'
                          }`}>
                            <span className="opacity-50">[{new Date(log.timestamp).toLocaleTimeString()}]</span> {log.message}
                          </div>
                        ))}
                        <div ref={(el) => el?.scrollIntoView({ behavior: 'smooth' })} />
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          )}

        </div>
      </div>
    </div>
  );
}

import { GoogleGenAI } from "@google/genai";
import { FileData } from "../types";

// Safety check for API Key
const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

const getFileSummaries = (files: FileData[]) => {
  return files.map(f => {
    let contentPreview = '';
    if (!f.isBinary && typeof f.content === 'string') {
        // Only include the first 200 chars of config-like files or code
        if (f.path.includes('json') || f.path.includes('md') || f.path.includes('js') || f.path.includes('ts') || f.path.includes('py')) {
            contentPreview = `\nContent Preview (start): ${f.content.substring(0, 300)}...`;
        }
    }
    return `- ${f.path} ${contentPreview}`;
  }).slice(0, 40).join('\n'); // Limit context
};

export const generateCommitMessage = async (files: FileData[], repoName: string): Promise<string> => {
  if (!API_KEY) {
    console.error("Gemini API Key is missing");
    return "Initial commit (Gemini key missing)";
  }

  const fileSummaries = getFileSummaries(files);

  const prompt = `
    I am pushing a project named "${repoName}" to GitHub.
    Here is a list of changed/new files:
    ${fileSummaries}

    ${files.length > 40 ? `...and ${files.length - 40} more files.` : ''}

    Generate a concise, professional Git commit message following Conventional Commits format (e.g., "feat: ...", "chore: ...").
    Do not include any markdown formatting, backticks, or explanations. Just the message string.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text.trim();
  } catch (error) {
    console.error("Gemini Error:", error);
    return `feat: initialize project ${repoName}`;
  }
};

export const generateProjectReadme = async (files: FileData[], repoName: string): Promise<string> => {
  if (!API_KEY) throw new Error("API Key missing");

  const fileSummaries = getFileSummaries(files);

  const prompt = `
    I need a professional README.md file for a GitHub project named "${repoName}".

    Based on the following file structure and content previews, infer the project's purpose, tech stack, and how to run it.

    Files:
    ${fileSummaries}

    Requirements:
    1. Use standard Markdown formatting.
    2. Include sections: Title, Description, Tech Stack, Installation/Usage (infer from package.json or file types if possible).
    3. Be concise but informative.
    4. Return ONLY the markdown content, no wrapping backticks.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    // Strip markdown code blocks if Gemini adds them accidentally
    let text = response.text.trim();
    if (text.startsWith('```markdown')) text = text.slice(11);
    if (text.startsWith('```')) text = text.slice(3);
    if (text.endsWith('```')) text = text.slice(0, -3);
    return text;
  } catch (error) {
    console.error("Gemini Readme Error:", error);
    throw new Error("Failed to generate README");
  }
};

import React, { useState, useEffect } from 'react';
import { StepIndicator } from './components/StepIndicator';
import { FileUploader } from './components/FileUploader';
import { FileData, UploadStatus, ProcessingLog, GitHubRepo } from './types';
import * as githubService from './services/githubService';
import * as geminiService from './services/geminiService';

export default function App() {
  const [step, setStep] = useState(1);

  // State: Auth
  const [token, setToken] = useState('');
  const [username, setUsername] = useState<string | null>(null);

  // State: Repo
  const [repoMode, setRepoMode] = useState<'create' | 'existing'>('create');
  const [userRepos, setUserRepos] = useState<GitHubRepo[]>([]);
  const [isLoadingRepos, setIsLoadingRepos] = useState(false);
  const [searchRepo, setSearchRepo] = useState('');

  const [repoName, setRepoName] = useState('');
  const [repoOwner, setRepoOwner] = useState('');
  const [isPrivate, setIsPrivate] = useState(true);
  const [branch, setBranch] = useState('main');

  // State: Files
  const [files, setFiles] = useState<FileData[]>([]);

  // State: Commit & Push
  const [commitMessage, setCommitMessage] = useState('');
  const [status, setStatus] = useState<UploadStatus>(UploadStatus.IDLE);
  const [logs, setLogs] = useState<ProcessingLog[]>([]);
  const [isGeneratingMsg, setIsGeneratingMsg] = useState(false);
  const [isGeneratingReadme, setIsGeneratingReadme] = useState(false);

  const addLog = (msg: string, type: 'info' | 'success' | 'error' = 'info') => {
    setLogs(prev => [...prev, { message: msg, type, timestamp: Date.now() }]);
  };

  // Fetch repos when entering Step 2
  useEffect(() => {
    if (step === 2 && token && userRepos.length === 0) {
      loadRepos();
    }
  }, [step, token]);

  const loadRepos = async () => {
    setIsLoadingRepos(true);
    const repos = await githubService.getUserRepos(token);
    setUserRepos(repos);
    setIsLoadingRepos(false);
  };

  // --- Step 1: Auth ---
  const handleTokenSubmit = async () => {
    if (!token) return;
    setStatus(UploadStatus.READING);
    const user = await githubService.validateToken(token);
    if (user) {
      setUsername(user);
      setRepoOwner(user); // Default owner is the authenticated user
      setStep(2);
      setStatus(UploadStatus.IDLE);
    } else {
      alert("Invalid GitHub Token");
      setStatus(UploadStatus.IDLE);
    }
  };

  // --- Step 2: Repo ---
  const handleRepoSubmit = async () => {
    if (!repoName || !repoOwner) return;
    setStatus(UploadStatus.READING);

    // Check if repo exists
    const exists = await githubService.checkRepoExists(token, repoOwner, repoName);

    if (exists) {
      // It exists, we will push to it
      addLog(`Repository ${repoOwner}/${repoName} found.`, 'success');
      setStep(3);
    } else {
      // Create it (only if in create mode or implicit)
      if (repoMode === 'existing') {
        addLog(`Repository ${repoOwner}/${repoName} not found.`, 'error');
        setStatus(UploadStatus.IDLE);
        return;
      }

      try {
        addLog(`Creating repository ${repoName}...`, 'info');
        const created = await githubService.createRepo(token, repoName, isPrivate);
        if (created) {
          addLog(`Repository ${repoName} created successfully.`, 'success');
          setStep(3);
        } else {
          addLog("Failed to create repository", 'error');
        }
      } catch (e) {
        addLog("Error creating repository", 'error');
      }
    }
    setStatus(UploadStatus.IDLE);
  };

  const handleExistingRepoSelect = (repo: GitHubRepo) => {
    setRepoName(repo.name);
    setRepoOwner(repo.owner.login);
    setBranch(repo.default_branch);
    setIsPrivate(repo.private);
  };

  // --- Step 3: Files ---
  const handleFilesSelected = (selectedFiles: FileData[]) => {
    if (selectedFiles.length === 0) return;
    setFiles(selectedFiles);
    setStep(4);
    // Auto-generate commit message suggestion
    handleGenerateCommitMessage(selectedFiles);
  };

  const handleRemoveFile = (indexToRemove: number) => {
    setFiles(prev => prev.filter((_, idx) => idx !== indexToRemove));
  };

  const handleGenerateCommitMessage = async (currentFiles: FileData[]) => {
    setIsGeneratingMsg(true);
    const msg = await geminiService.generateCommitMessage(currentFiles, repoName);
    setCommitMessage(msg);
    setIsGeneratingMsg(false);
  };

  const handleGenerateReadme = async () => {
    setIsGeneratingReadme(true);
    try {
      const readmeContent = await geminiService.generateProjectReadme(files, repoName);

      // Create new file object
      const newReadme: FileData = {
        path: 'README.md',
        content: readmeContent,
        isBinary: false,
        size: readmeContent.length
      };

      // Remove existing README if present, then add new one
      const filesWithoutReadme = files.filter(f => f.path.toLowerCase() !== 'readme.md');
      setFiles([newReadme, ...filesWithoutReadme]);

      addLog('README.md generated successfully!', 'success');
    } catch (e) {
      console.error(e);
      addLog('Failed to generate README', 'error');
    }
    setIsGeneratingReadme(false);
  };

  // --- Step 4: Push ---
  const handlePush = async () => {
    if (!repoOwner || !repoName || files.length === 0) return;
    setStatus(UploadStatus.UPLOADING);
    setLogs([]); // Clear previous logs

    try {
      addLog('Starting upload process...', 'info');
      await githubService.pushFilesToGitHub(
        token,
        repoOwner,
        repoName,
        branch,
        files,
        commitMessage || "Update project files",
        (msg) => addLog(msg, 'info')
      );
      setStatus(UploadStatus.SUCCESS);
      addLog('Project pushed successfully!', 'success');
    } catch (error: any) {
      console.error(error);
      setStatus(UploadStatus.ERROR);
      addLog(`Error: ${error.message}`, 'error');
    }
  };

  const reset = () => {
    setFiles([]);
    setStep(2);
    setStatus(UploadStatus.IDLE);
    setLogs([]);
    setCommitMessage('');
  };

  const filteredRepos = userRepos.filter(r => 
    r.full_name.toLowerCase().includes(searchRepo.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-slate-900 text-slate-50 flex flex-col items-center py-12 px-4">
      <div className="w-full max-w-5xl">
        <header className="mb-10 text-center">
          <h1 className="text-4xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-500 mb-2">
            GitGenius Pusher
          </h1>
          <p className="text-slate-400">Push local folders to GitHub directly from your browser.</p>
        </header>

        <StepIndicator currentStep={step} />

        <div className="bg-slate-800 rounded-2xl shadow-2xl border border-slate-700 p-8 min-h-[500px]">

          {/* STEP 1: AUTH */}
          {step === 1 && (
            <div className="flex flex-col gap-6 max-w-md mx-auto mt-8">
              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-300">GitHub Personal Access Token (Classic)</label>
                <input
                  type="password"
                  value={token}
                  onChange={(e) => setToken(e.target.value)}
                  placeholder="ghp_xxxxxxxxxxxx"
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                />
                <p className="text-xs text-slate-500">
                  Required scopes: <code>repo</code>, <code>user</code>. The token is only used locally and never stored on a server.
                </p>
              </div>
              <button
                onClick={handleTokenSubmit}
                disabled={status === UploadStatus.READING}
                className="w-full bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-3 px-6 rounded-lg transition-colors"
              >
                {status === UploadStatus.READING ? 'Verifying...' : 'Connect to GitHub'}
              </button>
            </div>
          )}

          {/* STEP 2: REPO DETAILS */}
          {step === 2 && (
            <div className="flex flex-col gap-6 max-w-md mx-auto mt-4">
              <div className="text-center mb-4">
                <p className="text-slate-400">Logged in as <span className="text-white font-bold">{username}</span></p>
              </div>

              {/* Toggle Mode */}
              <div className="flex p-1 bg-slate-900 rounded-lg mb-4 border border-slate-700">
                <button 
                  onClick={() => { setRepoMode('create'); setRepoName(''); setRepoOwner(username!); }}
                  className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${
                    repoMode === 'create' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'
                  }`}
                >
                  Create New
                </button>
                <button 
                   onClick={() => { setRepoMode('existing'); }}
                   className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${
                    repoMode === 'existing' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'
                   }`}
                >
                  Update Existing
                </button>
              </div>

              {repoMode === 'create' ? (
                <>
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-300">New Repository Name</label>
                    <input
                      type="text"
                      value={repoName}
                      onChange={(e) => setRepoName(e.target.value)}
                      placeholder="my-awesome-project"
                      className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-300">Branch</label>
                    <input
                      type="text"
                      value={branch}
                      onChange={(e) => setBranch(e.target.value)}
                      placeholder="main"
                      className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                    />
                  </div>
                  <div className="flex items-center gap-4 bg-slate-900 p-4 rounded-lg border border-slate-700">
                    <label className="flex items-center gap-2 cursor-pointer">
                      <input type="radio" checked={isPrivate} onChange={() => setIsPrivate(true)} className="w-4 h-4 text-blue-500" />
                      <span>Private</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer">
                      <input type="radio" checked={!isPrivate} onChange={() => setIsPrivate(false)} className="w-4 h-4 text-blue-500" />
                      <span>Public</span>
                    </label>
                  </div>
                </>
              ) : (
                <>
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-300">Select Repository</label>
                    {isLoadingRepos ? (
                      <div className="text-slate-500 text-sm animate-pulse">Loading repositories...</div>
                    ) : (
                      <>
                        <input
                           type="text"
                           value={searchRepo}
                           onChange={(e) => setSearchRepo(e.target.value)}
                           placeholder="Filter repositories..."
                           className="w-full mb-2 bg-slate-900 border border-slate-700 rounded-lg px-4 py-2 text-sm text-white focus:ring-1 focus:ring-blue-500 outline-none"
                        />
                        <div className="max-h-48 overflow-y-auto bg-slate-900 border border-slate-700 rounded-lg">
                           {filteredRepos.length === 0 ? (
                             <div className="p-3 text-sm text-slate-500 text-center">No repositories found</div>
                           ) : (
                             filteredRepos.map(repo => (
                               <div 
                                 key={repo.id}
                                 onClick={() => {
                                   handleExistingRepoSelect(repo);
                                   setSearchRepo(repo.full_name);
                                 }}
                                 className={`p-3 cursor-pointer text-sm hover:bg-slate-800 transition-colors flex justify-between items-center
                                   ${repoName === repo.name && repoOwner === repo.owner.login ? 'bg-blue-900/30 text-blue-300' : 'text-slate-300'}
                                 `}
                               >
                                 <span className="truncate pr-2">{repo.full_name}</span>
                                 {repo.private && <span className="text-xs bg-slate-800 border border-slate-600 px-1 rounded">Private</span>}
                               </div>
                             ))
                           )}
                        </div>
                      </>
                    )}
                  </div>
                  {repoName && (
                    <div className="space-y-2 bg-slate-900/50 p-3 rounded border border-slate-700/50">
                        <div className="text-xs text-slate-500">Target: <span className="text-slate-300">{repoOwner}/{repoName}</span></div>
                        <div className="flex items-center gap-2">
                             <label className="text-xs font-bold text-slate-400">Branch:</label>
                             <input 
                                type="text" 
                                value={branch} 
                                onChange={(e) => setBranch(e.target.value)}
                                className="bg-transparent border-b border-slate-600 text-sm text-white focus:border-blue-500 outline-none w-full"
                             />
                        </div>
                    </div>
                  )}
                </>
              )}

              <button
                onClick={handleRepoSubmit}
                disabled={!repoName || status === UploadStatus.READING}
                className="w-full bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white font-bold py-3 px-6 rounded-lg transition-colors mt-2"
              >
                {status === UploadStatus.READING ? 'Checking Repo...' : 'Next: Select Files'}
              </button>
            </div>
          )}

          {/* STEP 3: UPLOAD */}
          {step === 3 && (
            <div className="mt-8">
               <FileUploader onFilesSelected={handleFilesSelected} />
               <div className="mt-4 text-center">
                 <button onClick={() => setStep(2)} className="text-slate-400 hover:text-white underline text-sm">Back to Repo Settings</button>
               </div>
            </div>
          )}

          {/* STEP 4: REVIEW & PUSH */}
          {step === 4 && (
            <div className="flex flex-col lg:flex-row gap-8 h-full">
              {/* Left Col: File Summary */}
              <div className="flex-1 space-y-4">
                <div className="flex justify-between items-center">
                   <h3 className="text-xl font-bold text-white flex items-center">
                     <span className="mr-2">📄</span> {files.length} Files Ready
                   </h3>
                   <button
                     onClick={handleGenerateReadme}
                     disabled={isGeneratingReadme}
                     className="text-xs bg-orange-600/20 text-orange-300 hover:bg-orange-600/40 px-3 py-2 rounded transition-colors flex items-center gap-1 border border-orange-500/30"
                   >
                     {isGeneratingReadme ? <span className="animate-pulse">Writing...</span> : '📝 Generate README'}
                   </button>
                </div>

                <div className="bg-slate-900 rounded-lg p-2 h-96 overflow-y-auto border border-slate-700">
                  <ul className="space-y-1 text-sm text-slate-300">
                    {files.slice(0, 150).map((f, i) => (
                      <li key={i} className="flex justify-between items-center p-2 hover:bg-slate-800 rounded group">
                        <div className="flex items-center flex-1 truncate">
                          <span className="text-slate-500 mr-2">{f.isBinary ? '📦' : '📄'}</span>
                          <span className={`truncate ${f.path === 'README.md' ? 'text-orange-400 font-bold' : ''}`}>{f.path}</span>
                        </div>
                        <div className="flex items-center gap-3">
                           <span className="text-xs text-slate-600 whitespace-nowrap">{(f.size / 1024).toFixed(1)} KB</span>
                           <button 
                             onClick={() => handleRemoveFile(i)}
                             className="text-slate-600 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity p-1"
                             title="Remove file"
                           >
                             ✕
                           </button>
                        </div>
                      </li>
                    ))}
                    {files.length > 150 && (
                      <li className="text-center text-slate-500 italic pt-2">...and {files.length - 150} more</li>
                    )}
                  </ul>
                </div>
                <p className="text-xs text-slate-500 text-center">Hover over a file to remove it from the push.</p>
              </div>

              {/* Right Col: Commit Actions */}
              <div className="flex-1 space-y-6">
                <div className="space-y-2">
                  <div className="flex justify-between items-center">
                    <label className="text-sm font-bold text-slate-300">Commit Message</label>
                    <button 
                      onClick={() => handleGenerateCommitMessage(files)}
                      disabled={isGeneratingMsg}
                      className="text-xs bg-purple-600/20 text-purple-300 hover:bg-purple-600/40 px-2 py-1 rounded transition-colors flex items-center gap-1 border border-purple-500/30"
                    >
                      {isGeneratingMsg ? (
                        <span className="animate-pulse">Thinking...</span>
                      ) : (
                        <>✨ Rewrite with Gemini</>
                      )}
                    </button>
                  </div>
                  <textarea
                    value={commitMessage}
                    onChange={(e) => setCommitMessage(e.target.value)}
                    className="w-full h-32 bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none resize-none font-mono text-sm"
                    placeholder="feat: initial commit"
                  />
                </div>

                {status === UploadStatus.IDLE || status === UploadStatus.ERROR ? (
                   <button
                   onClick={handlePush}
                   className="w-full bg-green-600 hover:bg-green-500 text-white font-bold py-4 px-6 rounded-lg shadow-lg shadow-green-500/20 transition-all transform hover:scale-[1.02]"
                 >
                   🚀 Push to GitHub
                 </button>
                ) : (
                  <div className="bg-slate-900 rounded-lg p-4 border border-slate-700 h-40 overflow-y-auto">
                    {status === UploadStatus.SUCCESS ? (
                      <div className="flex flex-col items-center justify-center h-full text-green-400">
                         <span className="text-4xl mb-2">🎉</span>
                         <span className="font-bold">Upload Complete!</span>
                         <a 
                            href={`https://github.com/${repoOwner}/${repoName}/tree/${branch}`} 
                            target="_blank" 
                            rel="noreferrer"
                            className="mt-2 text-blue-400 hover:underline"
                          >
                            View Repository
                         </a>
                         <button onClick={reset} className="mt-4 text-xs text-slate-500 hover:text-white">Push another project</button>
                      </div>
                    ) : (
                      <div className="font-mono text-xs space-y-1">
                        {logs.map((log, i) => (
                          <div key={i} className={`${
                            log.type === 'error' ? 'text-red-400' : 
                            log.type === 'success' ? 'text-green-400' : 'text-slate-400'
                          }`}>
                            <span className="opacity-50">[{new Date(log.timestamp).toLocaleTimeString()}]</span> {log.message}
                          </div>
                        ))}
                        <div ref={(el) => el?.scrollIntoView({ behavior: 'smooth' })} />
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          )}

        </div>
      </div>
    </div>
  );
}

export interface FileData {
  path: string;
  content: string | ArrayBuffer;
  isBinary: boolean;
  size: number;
}

export enum UploadStatus {
  IDLE = 'IDLE',
  READING = 'READING',
  UPLOADING = 'UPLOADING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR',
}

export interface GitHubRepo {
  id: number;
  name: string;
  full_name: string;
  private: boolean;
  default_branch: string;
  owner: {
    login: string;
  };
  html_url: string;
  description: string | null;
}

export interface VercelProject {
  id: string;
  name: string;
  targets: {
    production?: {
      url: string;
    }
  };
  link?: {
    type: string;
    repo: string;
  };
}

export interface ProcessingLog {
  message: string;
  type: 'info' | 'success' | 'error';
  timestamp: number;
}

const VERCEL_API = 'https://api.vercel.com';

interface DeployResult {
  name: string;
  url: string;
  dashboardUrl: string;
}

export const deployToVercel = async (
  vercelToken: string,
  githubRepo: string, // "owner/repo"
  projectName: string,
  onLog: (msg: string) => void
): Promise<DeployResult> => {
  const headers = {
    Authorization: `Bearer ${vercelToken}`,
    'Content-Type': 'application/json',
  };

  onLog('Authenticating with Vercel...');

  // 1. Create or Get Project
  // We attempt to create a project linked to the GitHub repo.
  // If it exists, we catch the 409 Conflict and fetch the existing one.

  onLog(`Configuring Vercel project "${projectName}"...`);

  // Clean project name (Vercel requires lowercase, max 100 chars, etc.)
  const cleanName = projectName.toLowerCase().replace(/[^a-z0-9-]/g, '-').substring(0, 100);

  const createBody = {
    name: cleanName,
    gitRepository: {
      type: 'github',
      repo: githubRepo,
    },
    framework: null // Let Vercel auto-detect (Next.js, CRA, etc.)
  };

  let projectData: any;

  try {
    const createRes = await fetch(`${VERCEL_API}/v9/projects`, {
      method: 'POST',
      headers,
      body: JSON.stringify(createBody),
    });

    if (createRes.status === 409) {
      onLog('Project already exists on Vercel. Fetching details...');
      const getRes = await fetch(`${VERCEL_API}/v9/projects/${cleanName}`, { headers });
      if (!getRes.ok) throw new Error('Failed to fetch existing Vercel project.');
      projectData = await getRes.json();

      // Check if linked to the correct repo
      const linkedRepo = projectData.link?.repo;
      if (linkedRepo && linkedRepo !== githubRepo) {
        onLog(`Warning: This Vercel project is currently linked to "${linkedRepo}", not "${githubRepo}".`);
      } else if (!projectData.link) {
         onLog('Warning: Existing project is not linked to a git repository.');
      } else {
         onLog('Confirmed existing project link.');
      }
    } else if (!createRes.ok) {
      const err = await createRes.json();
      // Handle "missing_github_app" error specifically
      if (err.error?.code === 'missing_github_app' || err.code === 'missing_github_app') {
        throw new Error('Vercel does not have access to this GitHub repository. Please install the "Vercel" GitHub App on your account/org settings first.');
      }
      throw new Error(`Vercel API Error: ${err.error?.message || err.message || createRes.statusText}`);
    } else {
      projectData = await createRes.json();
      onLog('Vercel project created and linked to GitHub.');
    }

    onLog('Triggering deployment via GitHub integration...');

    // Note: Creating the project or updating the repo usually triggers a deployment automatically 
    // if the Vercel GitHub App is installed. We don't need to manually trigger a build 
    // unless we want to force it, but that requires different endpoints.
    // We return the expected URL.

    return {
      name: projectData.name,
      url: `https://${projectData.name}.vercel.app`,
      dashboardUrl: `https://vercel.com/${projectData.accountId}/${projectData.name}`
    };

  } catch (error) {
    console.error("Vercel Service Error:", error);
    throw error;
  }
};

import React from 'react';

interface StepIndicatorProps {
  currentStep: number;
}

const steps = ['Auth', 'Repo', 'Files', 'Push', 'Deploy'];

export const StepIndicator: React.FC<StepIndicatorProps> = ({ currentStep }) => {
  return (
    <div className="flex items-center justify-center w-full mb-8">
      {steps.map((label, idx) => {
        const stepNum = idx + 1;
        const isActive = stepNum === currentStep;
        const isCompleted = stepNum < currentStep;

        return (
          <div key={label} className="flex items-center">
            <div className={`flex items-center justify-center w-10 h-10 rounded-full border-2 font-bold transition-all duration-300
              ${isActive ? 'border-blue-500 text-blue-500 bg-blue-500/10 shadow-[0_0_15px_rgba(59,130,246,0.5)]' : 
                isCompleted ? 'border-green-500 text-green-500 bg-green-500/10' : 'border-slate-700 text-slate-500 bg-slate-800'
              }
            `}>
              {isCompleted ? '✓' : stepNum}
            </div>
            <span className={`ml-2 mr-6 text-sm font-medium ${isActive ? 'text-blue-400' : isCompleted ? 'text-green-400' : 'text-slate-600'}`}>
              {label}
            </span>
            {idx < steps.length - 1 && (
              <div className={`h-1 w-12 mr-4 rounded ${isCompleted ? 'bg-green-500/50' : 'bg-slate-800'}`} />
            )}
          </div>
        );
      })}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { StepIndicator } from './components/StepIndicator';
import { FileUploader } from './components/FileUploader';
import { FileData, UploadStatus, ProcessingLog, GitHubRepo } from './types';
import * as githubService from './services/githubService';
import * as geminiService from './services/geminiService';
import * as vercelService from './services/vercelService';

export default function App() {
  const [step, setStep] = useState(1);

  // State: Auth
  const [token, setToken] = useState('');
  const [username, setUsername] = useState<string | null>(null);

  // State: Repo
  const [repoMode, setRepoMode] = useState<'create' | 'existing'>('create');
  const [userRepos, setUserRepos] = useState<GitHubRepo[]>([]);
  const [isLoadingRepos, setIsLoadingRepos] = useState(false);
  const [searchRepo, setSearchRepo] = useState('');

  const [repoName, setRepoName] = useState('');
  const [repoOwner, setRepoOwner] = useState('');
  const [isPrivate, setIsPrivate] = useState(true);
  const [branch, setBranch] = useState('main');

  // State: Files
  const [files, setFiles] = useState<FileData[]>([]);

  // State: Commit & Push
  const [commitMessage, setCommitMessage] = useState('');
  const [status, setStatus] = useState<UploadStatus>(UploadStatus.IDLE);
  const [logs, setLogs] = useState<ProcessingLog[]>([]);
  const [isGeneratingMsg, setIsGeneratingMsg] = useState(false);
  const [isGeneratingReadme, setIsGeneratingReadme] = useState(false);

  // State: Vercel
  const [vercelToken, setVercelToken] = useState('');
  const [deployResult, setDeployResult] = useState<{name: string, url: string, dashboardUrl: string} | null>(null);

  const addLog = (msg: string, type: 'info' | 'success' | 'error' = 'info') => {
    setLogs(prev => [...prev, { message: msg, type, timestamp: Date.now() }]);
  };

  // Fetch repos when entering Step 2
  useEffect(() => {
    if (step === 2 && token && userRepos.length === 0) {
      loadRepos();
    }
  }, [step, token]);

  const loadRepos = async () => {
    setIsLoadingRepos(true);
    const repos = await githubService.getUserRepos(token);
    setUserRepos(repos);
    setIsLoadingRepos(false);
  };

  // --- Step 1: Auth ---
  const handleTokenSubmit = async () => {
    if (!token) return;
    setStatus(UploadStatus.READING);
    const user = await githubService.validateToken(token);
    if (user) {
      setUsername(user);
      setRepoOwner(user); // Default owner is the authenticated user
      setStep(2);
      setStatus(UploadStatus.IDLE);
    } else {
      alert("Invalid GitHub Token");
      setStatus(UploadStatus.IDLE);
    }
  };

  // --- Step 2: Repo ---
  const handleRepoSubmit = async () => {
    if (!repoName || !repoOwner) return;
    setStatus(UploadStatus.READING);

    // Check if repo exists
    const exists = await githubService.checkRepoExists(token, repoOwner, repoName);

    if (exists) {
      // It exists, we will push to it
      addLog(`Repository ${repoOwner}/${repoName} found.`, 'success');
      setStep(3);
    } else {
      // Create it (only if in create mode or implicit)
      if (repoMode === 'existing') {
        addLog(`Repository ${repoOwner}/${repoName} not found.`, 'error');
        setStatus(UploadStatus.IDLE);
        return;
      }

      try {
        addLog(`Creating repository ${repoName}...`, 'info');
        const created = await githubService.createRepo(token, repoName, isPrivate);
        if (created) {
          addLog(`Repository ${repoName} created successfully.`, 'success');
          setStep(3);
        } else {
          addLog("Failed to create repository", 'error');
        }
      } catch (e) {
        addLog("Error creating repository", 'error');
      }
    }
    setStatus(UploadStatus.IDLE);
  };

  const handleExistingRepoSelect = (repo: GitHubRepo) => {
    setRepoName(repo.name);
    setRepoOwner(repo.owner.login);
    setBranch(repo.default_branch);
    setIsPrivate(repo.private);
  };

  // --- Step 3: Files ---
  const handleFilesSelected = (selectedFiles: FileData[]) => {
    if (selectedFiles.length === 0) return;
    setFiles(selectedFiles);
    setStep(4);
    // Auto-generate commit message suggestion
    handleGenerateCommitMessage(selectedFiles);
  };

  const handleRemoveFile = (indexToRemove: number) => {
    setFiles(prev => prev.filter((_, idx) => idx !== indexToRemove));
  };

  const handleGenerateCommitMessage = async (currentFiles: FileData[]) => {
    setIsGeneratingMsg(true);
    const msg = await geminiService.generateCommitMessage(currentFiles, repoName);
    setCommitMessage(msg);
    setIsGeneratingMsg(false);
  };

  const handleGenerateReadme = async () => {
    setIsGeneratingReadme(true);
    try {
      const readmeContent = await geminiService.generateProjectReadme(files, repoName);

      // Create new file object
      const newReadme: FileData = {
        path: 'README.md',
        content: readmeContent,
        isBinary: false,
        size: readmeContent.length
      };

      // Remove existing README if present, then add new one
      const filesWithoutReadme = files.filter(f => f.path.toLowerCase() !== 'readme.md');
      setFiles([newReadme, ...filesWithoutReadme]);

      addLog('README.md generated successfully!', 'success');
    } catch (e) {
      console.error(e);
      addLog('Failed to generate README', 'error');
    }
    setIsGeneratingReadme(false);
  };

  // --- Step 4: Push ---
  const handlePush = async () => {
    if (!repoOwner || !repoName || files.length === 0) return;
    setStatus(UploadStatus.UPLOADING);
    setLogs([]); // Clear previous logs

    try {
      addLog('Starting upload process...', 'info');
      await githubService.pushFilesToGitHub(
        token,
        repoOwner,
        repoName,
        branch,
        files,
        commitMessage || "Update project files",
        (msg) => addLog(msg, 'info')
      );
      setStatus(UploadStatus.SUCCESS);
      addLog('Project pushed successfully!', 'success');
    } catch (error: any) {
      console.error(error);
      setStatus(UploadStatus.ERROR);
      addLog(`Error: ${error.message}`, 'error');
    }
  };

  // --- Step 5: Vercel Deploy ---
  const handleVercelDeploy = async () => {
    if (!vercelToken) {
      alert("Please enter a Vercel Access Token");
      return;
    }
    setStatus(UploadStatus.UPLOADING);
    setLogs([]); // Reset logs for deploy
    addLog("Initializing Vercel deployment...", 'info');

    try {
      const result = await vercelService.deployToVercel(
        vercelToken,
        `${repoOwner}/${repoName}`,
        repoName,
        (msg) => addLog(msg, 'info')
      );
      setDeployResult(result);
      setStatus(UploadStatus.SUCCESS);
      addLog("Deployment configured successfully!", 'success');
    } catch (error: any) {
      console.error(error);
      setStatus(UploadStatus.ERROR);
      addLog(`Deployment Error: ${error.message}`, 'error');
    }
  };

  const reset = () => {
    setFiles([]);
    setStep(2);
    setStatus(UploadStatus.IDLE);
    setLogs([]);
    setCommitMessage('');
    setDeployResult(null);
  };

  const filteredRepos = userRepos.filter(r => 
    r.full_name.toLowerCase().includes(searchRepo.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-slate-900 text-slate-50 flex flex-col items-center py-12 px-4">
      <div className="w-full max-w-5xl">
        <header className="mb-10 text-center">
          <h1 className="text-4xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-500 mb-2">
            GitGenius Pusher
          </h1>
          <p className="text-slate-400">Push local folders to GitHub & Deploy to Vercel.</p>
        </header>

        <StepIndicator currentStep={step} />

        <div className="bg-slate-800 rounded-2xl shadow-2xl border border-slate-700 p-8 min-h-[500px]">

          {/* STEP 1: AUTH */}
          {step === 1 && (
            <div className="flex flex-col gap-6 max-w-md mx-auto mt-8">
              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-300">GitHub Personal Access Token (Classic)</label>
                <input
                  type="password"
                  value={token}
                  onChange={(e) => setToken(e.target.value)}
                  placeholder="ghp_xxxxxxxxxxxx"
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                />
                <p className="text-xs text-slate-500">
                  Required scopes: <code>repo</code>, <code>user</code>. The token is only used locally and never stored on a server.
                </p>
              </div>
              <button
                onClick={handleTokenSubmit}
                disabled={status === UploadStatus.READING}
                className="w-full bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-3 px-6 rounded-lg transition-colors"
              >
                {status === UploadStatus.READING ? 'Verifying...' : 'Connect to GitHub'}
              </button>
            </div>
          )}

          {/* STEP 2: REPO DETAILS */}
          {step === 2 && (
            <div className="flex flex-col gap-6 max-w-md mx-auto mt-4">
              <div className="text-center mb-4">
                <p className="text-slate-400">Logged in as <span className="text-white font-bold">{username}</span></p>
              </div>

              {/* Toggle Mode */}
              <div className="flex p-1 bg-slate-900 rounded-lg mb-4 border border-slate-700">
                <button 
                  onClick={() => { setRepoMode('create'); setRepoName(''); setRepoOwner(username!); }}
                  className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${
                    repoMode === 'create' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'
                  }`}
                >
                  Create New
                </button>
                <button 
                   onClick={() => { setRepoMode('existing'); }}
                   className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${
                    repoMode === 'existing' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'
                   }`}
                >
                  Update Existing
                </button>
              </div>

              {repoMode === 'create' ? (
                <>
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-300">New Repository Name</label>
                    <input
                      type="text"
                      value={repoName}
                      onChange={(e) => setRepoName(e.target.value)}
                      placeholder="my-awesome-project"
                      className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-300">Branch</label>
                    <input
                      type="text"
                      value={branch}
                      onChange={(e) => setBranch(e.target.value)}
                      placeholder="main"
                      className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                    />
                  </div>
                  <div className="flex items-center gap-4 bg-slate-900 p-4 rounded-lg border border-slate-700">
                    <label className="flex items-center gap-2 cursor-pointer">
                      <input type="radio" checked={isPrivate} onChange={() => setIsPrivate(true)} className="w-4 h-4 text-blue-500" />
                      <span>Private</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer">
                      <input type="radio" checked={!isPrivate} onChange={() => setIsPrivate(false)} className="w-4 h-4 text-blue-500" />
                      <span>Public</span>
                    </label>
                  </div>
                </>
              ) : (
                <>
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-300">Select Repository</label>
                    {isLoadingRepos ? (
                      <div className="text-slate-500 text-sm animate-pulse">Loading repositories...</div>
                    ) : (
                      <>
                        <input
                           type="text"
                           value={searchRepo}
                           onChange={(e) => setSearchRepo(e.target.value)}
                           placeholder="Filter repositories..."
                           className="w-full mb-2 bg-slate-900 border border-slate-700 rounded-lg px-4 py-2 text-sm text-white focus:ring-1 focus:ring-blue-500 outline-none"
                        />
                        <div className="max-h-48 overflow-y-auto bg-slate-900 border border-slate-700 rounded-lg">
                           {filteredRepos.length === 0 ? (
                             <div className="p-3 text-sm text-slate-500 text-center">No repositories found</div>
                           ) : (
                             filteredRepos.map(repo => (
                               <div 
                                 key={repo.id}
                                 onClick={() => {
                                   handleExistingRepoSelect(repo);
                                   setSearchRepo(repo.full_name);
                                 }}
                                 className={`p-3 cursor-pointer text-sm hover:bg-slate-800 transition-colors flex justify-between items-center
                                   ${repoName === repo.name && repoOwner === repo.owner.login ? 'bg-blue-900/30 text-blue-300' : 'text-slate-300'}
                                 `}
                               >
                                 <span className="truncate pr-2">{repo.full_name}</span>
                                 {repo.private && <span className="text-xs bg-slate-800 border border-slate-600 px-1 rounded">Private</span>}
                               </div>
                             ))
                           )}
                        </div>
                      </>
                    )}
                  </div>
                  {repoName && (
                    <div className="space-y-2 bg-slate-900/50 p-3 rounded border border-slate-700/50">
                        <div className="text-xs text-slate-500">Target: <span className="text-slate-300">{repoOwner}/{repoName}</span></div>
                        <div className="flex items-center gap-2">
                             <label className="text-xs font-bold text-slate-400">Branch:</label>
                             <input 
                                type="text" 
                                value={branch} 
                                onChange={(e) => setBranch(e.target.value)}
                                className="bg-transparent border-b border-slate-600 text-sm text-white focus:border-blue-500 outline-none w-full"
                             />
                        </div>
                    </div>
                  )}
                </>
              )}

              <button
                onClick={handleRepoSubmit}
                disabled={!repoName || status === UploadStatus.READING}
                className="w-full bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white font-bold py-3 px-6 rounded-lg transition-colors mt-2"
              >
                {status === UploadStatus.READING ? 'Checking Repo...' : 'Next: Select Files'}
              </button>
            </div>
          )}

          {/* STEP 3: UPLOAD */}
          {step === 3 && (
            <div className="mt-8">
               <FileUploader onFilesSelected={handleFilesSelected} />
               <div className="mt-4 text-center">
                 <button onClick={() => setStep(2)} className="text-slate-400 hover:text-white underline text-sm">Back to Repo Settings</button>
               </div>
            </div>
          )}

          {/* STEP 4: REVIEW & PUSH */}
          {step === 4 && (
            <div className="flex flex-col lg:flex-row gap-8 h-full">
              {/* Left Col: File Summary */}
              <div className="flex-1 space-y-4">
                <div className="flex justify-between items-center">
                   <h3 className="text-xl font-bold text-white flex items-center">
                     <span className="mr-2">📄</span> {files.length} Files Ready
                   </h3>
                   <button
                     onClick={handleGenerateReadme}
                     disabled={isGeneratingReadme}
                     className="text-xs bg-orange-600/20 text-orange-300 hover:bg-orange-600/40 px-3 py-2 rounded transition-colors flex items-center gap-1 border border-orange-500/30"
                   >
                     {isGeneratingReadme ? <span className="animate-pulse">Writing...</span> : '📝 Generate README'}
                   </button>
                </div>

                <div className="bg-slate-900 rounded-lg p-2 h-96 overflow-y-auto border border-slate-700">
                  <ul className="space-y-1 text-sm text-slate-300">
                    {files.slice(0, 150).map((f, i) => (
                      <li key={i} className="flex justify-between items-center p-2 hover:bg-slate-800 rounded group">
                        <div className="flex items-center flex-1 truncate">
                          <span className="text-slate-500 mr-2">{f.isBinary ? '📦' : '📄'}</span>
                          <span className={`truncate ${f.path === 'README.md' ? 'text-orange-400 font-bold' : ''}`}>{f.path}</span>
                        </div>
                        <div className="flex items-center gap-3">
                           <span className="text-xs text-slate-600 whitespace-nowrap">{(f.size / 1024).toFixed(1)} KB</span>
                           <button 
                             onClick={() => handleRemoveFile(i)}
                             className="text-slate-600 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity p-1"
                             title="Remove file"
                           >
                             ✕
                           </button>
                        </div>
                      </li>
                    ))}
                    {files.length > 150 && (
                      <li className="text-center text-slate-500 italic pt-2">...and {files.length - 150} more</li>
                    )}
                  </ul>
                </div>
                <p className="text-xs text-slate-500 text-center">Hover over a file to remove it from the push.</p>
              </div>

              {/* Right Col: Commit Actions */}
              <div className="flex-1 space-y-6">
                <div className="space-y-2">
                  <div className="flex justify-between items-center">
                    <label className="text-sm font-bold text-slate-300">Commit Message</label>
                    <button 
                      onClick={() => handleGenerateCommitMessage(files)}
                      disabled={isGeneratingMsg}
                      className="text-xs bg-purple-600/20 text-purple-300 hover:bg-purple-600/40 px-2 py-1 rounded transition-colors flex items-center gap-1 border border-purple-500/30"
                    >
                      {isGeneratingMsg ? (
                        <span className="animate-pulse">Thinking...</span>
                      ) : (
                        <>✨ Rewrite with Gemini</>
                      )}
                    </button>
                  </div>
                  <textarea
                    value={commitMessage}
                    onChange={(e) => setCommitMessage(e.target.value)}
                    className="w-full h-32 bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none resize-none font-mono text-sm"
                    placeholder="feat: initial commit"
                  />
                </div>

                {status === UploadStatus.IDLE || status === UploadStatus.ERROR ? (
                   <button
                   onClick={handlePush}
                   className="w-full bg-green-600 hover:bg-green-500 text-white font-bold py-4 px-6 rounded-lg shadow-lg shadow-green-500/20 transition-all transform hover:scale-[1.02]"
                 >
                   🚀 Push to GitHub
                 </button>
                ) : (
                  <div className="bg-slate-900 rounded-lg p-4 border border-slate-700 h-40 overflow-y-auto">
                    {status === UploadStatus.SUCCESS ? (
                      <div className="flex flex-col items-center justify-center h-full text-green-400">
                         <span className="text-4xl mb-2">🎉</span>
                         <span className="font-bold">Push Complete!</span>
                         <a 
                            href={`https://github.com/${repoOwner}/${repoName}/tree/${branch}`} 
                            target="_blank" 
                            rel="noreferrer"
                            className="mt-2 text-blue-400 hover:underline"
                          >
                            View Repository
                         </a>
                         <button 
                           onClick={() => {
                             setStatus(UploadStatus.IDLE);
                             setLogs([]);
                             setStep(5);
                           }} 
                           className="mt-6 bg-black text-white px-6 py-3 rounded-lg font-bold border border-slate-700 hover:bg-slate-900 transition-colors shadow-lg flex items-center"
                         >
                           <svg viewBox="0 0 1155 1000" className="w-4 h-4 mr-2 fill-white"><path d="M577.344 0L1154.69 1000H0L577.344 0Z" /></svg>
                           Deploy to Vercel
                         </button>
                         <button onClick={reset} className="mt-4 text-xs text-slate-500 hover:text-white underline">Or push another project</button>
                      </div>
                    ) : (
                      <div className="font-mono text-xs space-y-1">
                        {logs.map((log, i) => (
                          <div key={i} className={`${
                            log.type === 'error' ? 'text-red-400' : 
                            log.type === 'success' ? 'text-green-400' : 'text-slate-400'
                          }`}>
                            <span className="opacity-50">[{new Date(log.timestamp).toLocaleTimeString()}]</span> {log.message}
                          </div>
                        ))}
                        <div ref={(el) => el?.scrollIntoView({ behavior: 'smooth' })} />
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          )}

          {/* STEP 5: VERCEL DEPLOY */}
          {step === 5 && (
            <div className="max-w-md mx-auto mt-8 flex flex-col gap-6">
               <div className="text-center">
                  <h3 className="text-2xl font-bold text-white mb-2">Deploy to Vercel</h3>
                  <p className="text-slate-400 text-sm">
                    Link your GitHub repository to Vercel to enable continuous deployment.
                    <br/>
                    <span className="text-xs text-yellow-500/80">Note: Ensure "Vercel" is installed on your GitHub account.</span>
                  </p>
               </div>

               <div className="space-y-2">
                 <label className="text-sm font-bold text-slate-300">Vercel Access Token</label>
                 <input
                   type="password"
                   value={vercelToken}
                   onChange={(e) => setVercelToken(e.target.value)}
                   placeholder="ex: regular-deployment-token"
                   className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-black outline-none"
                 />
                 <a href="https://vercel.com/account/tokens" target="_blank" rel="noreferrer" className="text-xs text-blue-400 hover:underline">Get a token here</a>
               </div>

               {status === UploadStatus.IDLE || status === UploadStatus.ERROR ? (
                   <button
                   onClick={handleVercelDeploy}
                   className="w-full bg-white text-black hover:bg-slate-200 font-bold py-3 px-6 rounded-lg shadow-lg transition-all transform hover:scale-[1.02] flex justify-center items-center"
                 >
                   <svg viewBox="0 0 1155 1000" className="w-4 h-4 mr-2 fill-black"><path d="M577.344 0L1154.69 1000H0L577.344 0Z" /></svg>
                   Deploy Project
                 </button>
               ) : (
                  <div className="bg-slate-900 rounded-lg p-4 border border-slate-700 h-48 overflow-y-auto">
                    {status === UploadStatus.SUCCESS && deployResult ? (
                       <div className="flex flex-col items-center justify-center h-full text-center">
                         <span className="text-4xl mb-2">🚀</span>
                         <h4 className="font-bold text-white">Project Created!</h4>
                         <a href={deployResult.url} target="_blank" rel="noreferrer" className="text-blue-400 hover:underline mt-1 font-mono text-sm">{deployResult.url}</a>
                         <a href={deployResult.dashboardUrl} target="_blank" rel="noreferrer" className="text-xs text-slate-500 hover:text-white mt-2 border border-slate-700 px-2 py-1 rounded">Open Dashboard</a>
                         <button onClick={reset} className="mt-4 text-xs text-slate-600 hover:text-slate-400">Start Over</button>
                       </div>
                    ) : (
                      <div className="font-mono text-xs space-y-1">
                        {logs.map((log, i) => (
                          <div key={i} className={`${
                            log.type === 'error' ? 'text-red-400' : 
                            log.type === 'success' ? 'text-green-400' : 'text-slate-400'
                          }`}>
                            <span className="opacity-50">[{new Date(log.timestamp).toLocaleTimeString()}]</span> {log.message}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
               )}
            </div>
          )}

        </div>
      </div>
    </div>
  );
}

import React, { useRef, useState } from 'react';
import { FileData } from '../types';

interface FileUploaderProps {
  onFilesSelected: (files: FileData[]) => void;
}

export const FileUploader: React.FC<FileUploaderProps> = ({ onFilesSelected }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setIsProcessing(true);
      const files: FileData[] = [];
      // Explicitly cast to File[] to fix 'unknown' type inference error
      const fileList = Array.from(e.target.files) as File[];

      // Process files
      for (const file of fileList) {
        // webkitRelativePath is available when uploading directories
        // Example: "MyProject/src/index.js"
        const rawPath = file.webkitRelativePath || file.name;

        // We want to strip the top-level folder name so that the CONTENTS of the selected folder
        // become the ROOT of the GitHub repository.
        // Example transformation: "MyProject/src/index.js" -> "src/index.js"
        const pathParts = rawPath.split('/');
        let relativePath = rawPath;

        if (pathParts.length > 1) {
            relativePath = pathParts.slice(1).join('/');
        }

        // Exclude node_modules and .git folders/files
        if (
             relativePath.includes('node_modules') || 
             relativePath.includes('.git/') || 
             relativePath.startsWith('.git/') ||
             relativePath === '.git'
        ) {
          continue;
        }

        // Skip if relativePath became empty (e.g. if the file was just the folder handle itself, though unlikely in File API)
        if (!relativePath) continue;

        const isBinary = isBinaryFile(file.name);
        try {
          const content = await readFileContent(file, isBinary);

          files.push({
            path: relativePath, // Preserves folder structure (minus root)
            content,
            isBinary,
            size: file.size,
          });
        } catch (err) {
          console.warn(`Skipping file ${file.name}:`, err);
        }
      }

      onFilesSelected(files);
      setIsProcessing(false);
    }
  };

  const isBinaryFile = (fileName: string): boolean => {
    const extensions = ['png', 'jpg', 'jpeg', 'gif', 'ico', 'pdf', 'zip', 'exe', 'bin', 'mp4', 'mp3', 'woff', 'woff2', 'ttf', 'eot', 'svg', 'mov', 'webm'];
    const ext = fileName.split('.').pop()?.toLowerCase();
    return ext ? extensions.includes(ext) : false;
  };

  const readFileContent = (file: File, isBinary: boolean): Promise<string | ArrayBuffer> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        if (e.target?.result) resolve(e.target.result);
        else reject(new Error("Empty file"));
      };
      reader.onerror = (e) => reject(e);

      if (isBinary) {
        reader.readAsArrayBuffer(file);
      } else {
        reader.readAsText(file);
      }
    });
  };

  return (
    <div className="w-full flex flex-col items-center justify-center p-8 border-2 border-dashed border-slate-700 rounded-xl bg-slate-800/50 hover:bg-slate-800 transition-colors">
      <div className="mb-4 text-6xl">📂</div>
      <h3 className="text-xl font-semibold mb-2 text-slate-200">Select Project Folder</h3>
      <p className="text-slate-400 text-center mb-6 max-w-md">
        Click to select a directory. The <strong>contents</strong> of the folder will be pushed to the root of your repository.
        <br/><span className="text-xs text-yellow-500/80">(node_modules and .git are automatically ignored)</span>
      </p>

      {isProcessing ? (
        <div className="flex items-center text-blue-400">
          <svg className="animate-spin h-5 w-5 mr-3" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
          Processing files...
        </div>
      ) : (
        <button
          onClick={() => fileInputRef.current?.click()}
          className="bg-blue-600 hover:bg-blue-500 text-white font-semibold py-3 px-8 rounded-lg shadow-lg shadow-blue-500/30 transition-all transform hover:scale-105"
        >
          Browse Folder
        </button>
      )}

      {/* 
        IMPORTANT: webkitdirectory attribute is non-standard but needed for folder selection.
        React TS doesn't natively support it on input types without module augmentation or casting.
      */}
      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChange}
        className="hidden"
        {...({ webkitdirectory: "", directory: "" } as any)} 
      />
    </div>
  );
};

import { FileData, GitHubRepo } from '../types';

const GITHUB_API_BASE = 'https://api.github.com';

interface GitBlob {
  sha: string;
  path: string;
  mode: string;
  type: string;
}

// Helper to encode array buffer to base64
function arrayBufferToBase64(buffer: ArrayBuffer): string {
  let binary = '';
  const bytes = new Uint8Array(buffer);
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return window.btoa(binary);
}

export const validateToken = async (token: string): Promise<string | null> => {
  try {
    const response = await fetch(`${GITHUB_API_BASE}/user`, {
      headers: {
        Authorization: `token ${token}`,
        Accept: 'application/vnd.github.v3+json',
      },
    });
    if (!response.ok) return null;
    const data = await response.json();
    return data.login; // Return username
  } catch (e) {
    return null;
  }
};

export const getUserRepos = async (token: string): Promise<GitHubRepo[]> => {
  try {
    // Fetch up to 100 recently updated repos
    const response = await fetch(`${GITHUB_API_BASE}/user/repos?sort=updated&per_page=100`, {
      headers: {
        Authorization: `token ${token}`,
        Accept: 'application/vnd.github.v3+json',
      },
    });
    if (!response.ok) return [];
    return await response.json();
  } catch (e) {
    console.error("Error fetching repos:", e);
    return [];
  }
};

export const checkRepoExists = async (token: string, owner: string, repo: string): Promise<boolean> => {
  const response = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}`, {
    headers: { Authorization: `token ${token}` },
  });
  return response.status === 200;
};

export const createRepo = async (token: string, name: string, isPrivate: boolean): Promise<boolean> => {
  const response = await fetch(`${GITHUB_API_BASE}/user/repos`, {
    method: 'POST',
    headers: {
      Authorization: `token ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      name,
      private: isPrivate,
      auto_init: true, // Initialize so we have a main branch
    }),
  });
  return response.ok;
};

// Core logic: Push files using Git Database API
export const pushFilesToGitHub = async (
  token: string,
  owner: string,
  repo: string,
  branch: string,
  files: FileData[],
  commitMessage: string,
  onProgress: (msg: string) => void
): Promise<void> => {
  const headers = {
    Authorization: `token ${token}`,
    Accept: 'application/vnd.github.v3+json',
    'Content-Type': 'application/json',
  };

  // 1. Get reference to current head (ONLY to get the parent commit SHA)
  onProgress('Fetching repository status...');
  let latestCommitSha: string | null = null;

  // Note: We DO NOT fetch the baseTreeSha anymore.
  // By omitting base_tree in the tree creation step, we effectively say:
  // "The new tree contains ONLY the files provided in this request."
  // This implicitly deletes any files that were in the previous commit but not in this upload.

  try {
    const refRes = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/git/refs/heads/${branch}`, { headers });
    if (refRes.ok) {
      const refData = await refRes.json();
      latestCommitSha = refData.object.sha;
    } else {
      onProgress('Branch not found. Starting fresh commit tree.');
    }
  } catch (e) {
    console.warn('Could not fetch refs, assuming empty repo.');
  }

  // 2. Create Blobs for each file
  const treeItems: { path: string; mode: string; type: string; sha: string | null }[] = [];

  // Parallelize uploads in chunks
  const CHUNK_SIZE = 5;
  for (let i = 0; i < files.length; i += CHUNK_SIZE) {
    const chunk = files.slice(i, i + CHUNK_SIZE);
    await Promise.all(chunk.map(async (file) => {
      onProgress(`Uploading ${file.path}...`);

      let content: string;
      let encoding: 'utf-8' | 'base64';

      if (file.isBinary && file.content instanceof ArrayBuffer) {
        content = arrayBufferToBase64(file.content);
        encoding = 'base64';
      } else {
        content = file.content as string;
        encoding = 'utf-8';
      }

      try {
        const blobRes = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/git/blobs`, {
          method: 'POST',
          headers,
          body: JSON.stringify({ content, encoding }),
        });

        if (!blobRes.ok) throw new Error(`Failed to upload ${file.path}`);

        const blobData = await blobRes.json();
        treeItems.push({
          path: file.path,
          mode: '100644', 
          type: 'blob',
          sha: blobData.sha,
        });
      } catch (e) {
        onProgress(`Error uploading ${file.path}: ${e}`);
        throw e;
      }
    }));
  }

  // 3. Create a Tree
  onProgress('Building file tree (replacing old content)...');

  // IMPORTANT: We do NOT include 'base_tree'. 
  // This forces the repo to match exactly the 'treeItems' provided, deleting anything else.
  const treePayload: any = {
    tree: treeItems,
  };

  const treeRes = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/git/trees`, {
    method: 'POST',
    headers,
    body: JSON.stringify(treePayload),
  });

  if (!treeRes.ok) {
      const err = await treeRes.text();
      throw new Error(`Failed to create tree: ${err}`);
  }
  const treeData = await treeRes.json();
  const newTreeSha = treeData.sha;

  // 4. Create Commit
  onProgress('Finalizing commit...');
  const commitPayload: any = {
    message: commitMessage,
    tree: newTreeSha,
  };

  // We still link the parent commit so Git history is preserved
  if (latestCommitSha) {
    commitPayload.parents = [latestCommitSha];
  }

  const newCommitRes = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/git/commits`, {
    method: 'POST',
    headers,
    body: JSON.stringify(commitPayload),
  });

  if (!newCommitRes.ok) throw new Error('Failed to create commit');
  const newCommitData = await newCommitRes.json();
  const newCommitSha = newCommitData.sha;

  // 5. Update Reference (The actual "Push")
  onProgress('Pushing to branch...');

  const refUrl = latestCommitSha 
    ? `${GITHUB_API_BASE}/repos/${owner}/${repo}/git/refs/heads/${branch}`
    : `${GITHUB_API_BASE}/repos/${owner}/${repo}/git/refs`;

  const method = latestCommitSha ? 'PATCH' : 'POST';
  const body = latestCommitSha 
    ? { sha: newCommitSha }
    : { ref: `refs/heads/${branch}`, sha: newCommitSha };

  const finalRes = await fetch(refUrl, {
    method,
    headers,
    body: JSON.stringify(body),
  });

  if (!finalRes.ok) throw new Error('Failed to update branch reference');
  onProgress('Push complete!');
};
